    /// Drain the callback-parked `SendMessageQuery` answers.
    fn dispatch_completed_send_message_net(&mut self) {
        let completed = std::mem::take(&mut *self.send_message_net_completed.lock());
        for (random_id, dialog_id, query) in completed {
            self.on_send_message_answer(random_id, dialog_id, query);
        }
    }

    /// `MessagesManager::check_send_message_result` (MessagesManager.cpp:27784-27807)
    /// over the M.7.8 statics; the wrong-result repair legs (the channel
    /// difference / the scheduled-messages repair) stay the recorded
    /// seams — the log band is the observable part.
    fn check_send_message_result(
        &mut self,
        random_id: i64,
        dialog_id: crate::messages_manager::DialogId,
        updates: &telegram_api::Updates,
    ) {
        let sent_messages = crate::updates_manager::get_new_messages(updates);
        let sent_random_ids = crate::updates_manager::get_sent_messages_random_ids(updates);
        let wrong = sent_messages.len() != 1
            || sent_random_ids.len() != 1
            || !sent_random_ids.contains(&random_id)
            || crate::messages_manager::DialogId::get_message_dialog_id(sent_messages[0].0)
                != dialog_id;
        if wrong {
            tdutils::log_error!(
                "Receive wrong result for sending message with random_id {random_id} to {dialog_id}"
            );
        }
    }

    /// Drain the callback-parked messages-plane answers — the C++
    /// `GetChannelDifferenceQuery::on_result`/`on_error` halves
    /// (MessagesManager.cpp:2257-2275).
    fn dispatch_completed_messages_net(&mut self) {
        let completed = std::mem::take(&mut *self.messages_net_completed.lock());
        for (kind, query) in completed {
            self.on_messages_net_answer(kind, query);
        }
        self.drain_sink();
    }

    /// Route one messages-plane net answer by kind — the answer parses
    /// at the ResultHandler shape, the error head runs
    /// `on_get_dialog_error` (suppressed only for the log gate), then the
    /// ladder's `on_get_channel_difference` runs over the split-context
    /// alias pair.
    fn on_messages_net_answer(
        &mut self,
        kind: crate::messages_manager::MessagesNetKind,
        query: NetQuery,
    ) {
        match kind {
            // `GetChannelDifferenceQuery` (MessagesManager.cpp:2240-2275)
            crate::messages_manager::MessagesNetKind::GetChannelDifference {
                dialog_id,
                pts,
                limit,
            } => {
                let result = if query.is_error() {
                    let status = query.error().clone();
                    // the `on_error` head (cpp:2266-2274): the head always
                    // runs; the error log is gated on head-false && not
                    // PERSISTENT_TIMESTAMP_INVALID
                    crate::dialog_manager::on_get_dialog_error(
                        &self.global,
                        dialog_id,
                        &status,
                        "GetChannelDifferenceQuery",
                    );
                    Err(status)
                } else {
                    match telegram_api::updates_ChannelDifference::parse(query.ok()) {
                        Ok(difference) => Ok(difference),
                        Err(_) => Err(Status::error(
                            500,
                            "Failed to parse the updates_getChannelDifference answer",
                        )),
                    }
                };
                // SAFETY: the alias pair derives from `td_ptr`; the
                // ladder uses the contexts strictly one at a time
                // (global/manager/ctxs never alias the same field
                // simultaneously).
                let td_ptr = std::ptr::from_mut(self);
                let manager: &mut crate::messages_manager::MessagesManager =
                    unsafe { &mut (*td_ptr).messages_manager };
                let global: &mut crate::global::Global = unsafe { &mut (*td_ptr).global };
                let msgctx: &mut dyn crate::messages_manager::MessageObjectContext =
                    unsafe { &mut *td_ptr };
                let state: &mut dyn crate::messages_manager::ReadStateContext =
                    unsafe { crate::td::split_context_alias(td_ptr) };
                let cdctx: &mut dyn crate::messages_manager::ChannelDifferenceContext =
                    unsafe { &mut *td_ptr };
                // SAFETY: as the pair above — the shared-ref contexts
                // (the C++ `d` reads only).
                let sendctx: &dyn crate::messages_manager::SendMessageContext = unsafe { &*td_ptr };
                let reactions_ctx: &dyn crate::messages_manager::DialogReactionsContext =
                    unsafe { &*td_ptr };
                crate::messages_manager::on_get_channel_difference(
                    global,
                    manager,
                    msgctx,
                    state,
                    sendctx,
                    reactions_ctx,
                    cdctx,
                    dialog_id,
                    pts,
                    limit,
                    result,
                );
            }
            // `SendPaidReactionQuery::on_result`/`on_error`
            // (MessageReaction.cpp:121-146) — the star-balance ledger
            // re-add, then the updates re-enter the engine with the
            // `on_set_message_reactions` chain; the error bands settle
            // through the same chain (the MESSAGE_NOT_MODIFIED ok band
            // included).
            crate::messages_manager::MessagesNetKind::SendPaidReaction {
                dialog_id,
                star_count,
            } => {
                let Some((message_full_id, promise)) =
                    crate::messages_manager::pop_paid_reaction_promise(&mut self.messages_manager)
                else {
                    return;
                };
                if query.is_error() {
                    let status = query.error().clone();
                    // the `on_error` head (MessageReaction.cpp:132-145)
                    if status.message() == "MESSAGE_NOT_MODIFIED" {
                        self.star_add_pending_owned(star_count, true);
                        self.on_set_message_reactions_chain(
                            message_full_id,
                            tdutils::status::Result::Ok(()),
                            promise,
                        );
                        return;
                    }
                    self.star_add_pending_owned(star_count, false);
                    crate::dialog_manager::on_get_dialog_error(
                        &self.global,
                        dialog_id,
                        &status,
                        "SendPaidReactionQuery",
                    );
                    self.on_set_message_reactions_chain(
                        message_full_id,
                        tdutils::status::Result::Err(status),
                        promise,
                    );
                    return;
                }
                let updates = match telegram_api::Updates::parse(query.ok()) {
                    Result::Ok(updates) => updates,
                    Result::Err(_) => {
                        // the fetch_result parse failure runs on_error with
                        // the 500 (the C++ `fetch_result` error path)
                        let status = Status::error(
                            500,
                            "Failed to parse the messages_sendPaidReaction answer",
                        );
                        self.star_add_pending_owned(star_count, false);
                        self.on_set_message_reactions_chain(
                            message_full_id,
                            tdutils::status::Result::Err(status),
                            promise,
                        );
                        return;
                    }
                };
                // the ok half (MessageReaction.cpp:125-130): the ledger
                // re-add (is_final), then the updates run through the
                // engine with the promise chain
                self.star_add_pending_owned(star_count, true);
                self.um_send_later(UmMessage::OnGetUpdatesPaidReaction {
                    updates: Box::new(updates),
                    message_full_id,
                    promise,
                });
                self.drain_sink();
            }
            // `TogglePaidReactionPrivacyQuery::on_result`/`on_error`
            // (MessageReaction.cpp:172-187) — the promise settles
            // directly; the error head runs the dialog error intake.
            crate::messages_manager::MessagesNetKind::TogglePaidReactionPrivacy { dialog_id } => {
                let Some(mut promise) = crate::messages_manager::pop_paid_reaction_privacy_promise(
                    &mut self.messages_manager,
                ) else {
                    return;
                };
                if query.is_error() {
                    let status = query.error().clone();
                    crate::dialog_manager::on_get_dialog_error(
                        &self.global,
                        dialog_id,
                        &status,
                        "TogglePaidReactionPrivacyQuery",
                    );
                    promise.set_error(status);
                    return;
                }
                match parse_wire_bool(query.ok()) {
                    Some(()) => promise.set_value(()),
                    // the fetch failure runs on_error with the 500
                    None => promise.set_error(Status::error(
                        500,
                        "Failed to parse the messages_togglePaidReactionPrivacy answer",
                    )),
                }
            }
        }
    }

    /// Route one auth answer (the two-step `CheckPassword` re-dispatches
    /// inside).
    fn on_auth_answer(
        &mut self,
        request_id: u64,
        kind: AuthPendingKind,
        answer: Option<&[u8]>,
        error: Option<&str>,
    ) {
        // The sign-in `SESSION_PASSWORD_NEEDED` turn: the C++ fetches the
        // password state (`account.getPassword`) and answers WaitPassword.
        if matches!(kind, AuthPendingKind::SignIn) && error == Some("SESSION_PASSWORD_NEEDED") {
            let function =
                telegram_api::Function::account_getPassword(telegram_api::account_getPassword);
            let token = self.park_net(
                request_id,
                PendingNetKind::Auth(AuthPendingKind::GetPassword),
            );
            return self.dispatch_walking_query(token, function, AuthFlag::On);
        }
        match parse_auth_answer(&kind, answer, error) {
            tdutils::status::Result::Ok(AuthAnswer::SentCode(result)) => {
                match self.auth_manager.on_sent_code_result(result) {
                    Ok(()) => {
                        self.flush_auth_updates();
                        self.send_result(request_id, ok_object());
                    }
                    Err(message) => self.send_error_impl(request_id, 400, &message),
                }
            }
            tdutils::status::Result::Ok(AuthAnswer::Authorization { user_id, user }) => {
                let result = crate::auth_manager::AuthNetResult::Authorization {
                    user_id,
                    terms_of_service: None,
                };
                let applied = match kind {
                    AuthPendingKind::SignIn => self.auth_manager.on_authorization_result(result),
                    AuthPendingKind::BotToken => self.auth_manager.on_bot_token_result(result),
                    _ => unreachable!("authorization from an unexpected auth step"),
                };
                match applied {
                    Ok(()) => {
                        if self.auth_manager.is_authorized() {
                            self.complete_authorization(request_id, user.as_ref());
                        } else {
                            // WaitRegistration — updates then ok.
                            self.flush_auth_updates();
                            self.send_result(request_id, ok_object());
                        }
                    }
                    Err(message) => self.send_error_impl(request_id, 400, &message),
                }
            }
            tdutils::status::Result::Ok(AuthAnswer::PasswordSrp { srp }) => {
                let function = build_check_password_function(srp);
                let token = self.park_net(
                    request_id,
                    PendingNetKind::Auth(AuthPendingKind::CheckPasswordStep2),
                );
                self.dispatch_walking_query(token, function, AuthFlag::On);
            }
            tdutils::status::Result::Ok(AuthAnswer::PasswordOk { user }) => {
                match self
                    .auth_manager
                    .on_password_result(crate::auth_manager::AuthNetResult::PasswordOk)
                {
                    Ok(()) => self.complete_authorization(request_id, user.as_ref()),
                    Err(message) => self.send_error_impl(request_id, 400, &message),
                }
            }
            tdutils::status::Result::Ok(AuthAnswer::PasswordState {
                wait_password_state,
            }) => {
                self.auth_manager.on_password_needed(wait_password_state);
                self.flush_auth_updates();
                self.send_result(request_id, ok_object());
            }
            tdutils::status::Result::Ok(AuthAnswer::LoggedOut) => {
                self.auth_manager.on_logged_out();
                if let Some(dc_auth_manager) = self.dc_auth_manager.as_mut() {
                    dc_auth_manager.destroy();
                }
                self.flush_auth_updates();
                self.send_result(request_id, ok_object());
            }
            tdutils::status::Result::Err(status) => {
                // A failed bot-token query still completes it — the C++
                // `on_result` clears `net_query_type_` on errors too
                // (AuthManager.cpp:1571).
                if matches!(kind, AuthPendingKind::BotToken) {
                    self.auth_manager.abort_bot_token_query();
                }
                self.send_error_impl(request_id, 400, status.message())
            }
        }
    }

    /// Route one PhoneNumberManager answer (the glue slice): the send/
    /// resend answers apply through the manager (the generation guard),
    /// the change-phone check applies the returned self user (the C++
    /// `ChangePhoneQuery::on_result`), the rest answer ok.
    fn on_phone_answer(
        &mut self,
        request_id: u64,
        kind: PhonePendingKind,
        answer: Option<&[u8]>,
        error: Option<&Status>,
    ) {
        let generation = kind.generation();
        match crate::phone_number_manager::parse_phone_answer(&kind, answer, error) {
            tdutils::status::Result::Ok(PhoneAnswer::SentCode(sent_code)) => {
                let generation = generation.unwrap_or_default();
                match self
                    .phone_number_manager
                    .on_send_code_result(generation, sent_code)
                {
                    tdutils::status::Result::Ok(code_info) => {
                        self.send_result(request_id, Object::authenticationCodeInfo(code_info));
                    }
                    tdutils::status::Result::Err(status) => {
                        self.send_error_impl(request_id, status.code(), status.message())
                    }
                }
            }
            tdutils::status::Result::Ok(PhoneAnswer::ChangedUser(user)) => {
                // ChangePhoneQuery::on_result — the changed self user
                // applies before the ok (PhoneNumberManager.cpp:124).
                self.apply_self_user(&user, true);
                self.finish_check_code(request_id, generation);
            }
            tdutils::status::Result::Ok(PhoneAnswer::Ok) => match kind {
                PhonePendingKind::CheckCode { .. } => {
                    self.finish_check_code(request_id, generation);
                }
                // Firebase/report answers carry no manager state change.
                _ => self.send_result(request_id, ok_object()),
            },
            tdutils::status::Result::Err(status) => {
                self.send_error_impl(request_id, status.code(), status.message())
            }
        }
    }

    /// `PhoneNumberManager::on_check_code_result` + the ok (the glue
    /// slice's check-code completion tail).
    fn finish_check_code(&mut self, request_id: u64, generation: Option<i64>) {
        match self
            .phone_number_manager
            .on_check_code_result(generation.unwrap_or_default())
        {
            tdutils::status::Result::Ok(()) => self.send_result(request_id, ok_object()),
            tdutils::status::Result::Err(status) => {
                self.send_error_impl(request_id, status.code(), status.message())
            }
        }
    }

    /// `G()->unix_time()` — the server-time-corrected wall clock; the value
    /// comes from the Global hub inited at `Td::init` (before this, without
    /// a session the server difference is just the local default).
    pub(crate) fn get_unix_time(&self) -> i32 {
        self.global.unix_time()
    }

    /// A completed ConfigManager query — the C++ `ConfigManager::on_result`
    /// token dispatch. The net step calls this when a pending query
    /// completes; tests drive the config flow through it.
    pub(crate) fn on_config_query_result(&mut self, query: ConfigQuery, result: ConfigQueryResult) {
        let close_flag = self.close_flag != 0;
        let is_authorized = self.auth_manager.is_authorized();
        let is_bot = self.auth_manager.is_bot();
        let is_test_dc = self.global.is_test_dc();
        let main_dc_id = self.get_main_dc_id();
        let Some(config_manager) = self.config_manager.as_mut() else {
            return;
        };
        let actions = {
            let pmc = self.global.binlog_pmc();
            let option_manager = self
                .option_manager
                .as_mut()
                .expect("option manager set in Run");
            match (query, result) {
                (
                    ConfigQuery::GetConfig {
                        dc_id: _,
                        reopen_sessions,
                    },
                    ConfigQueryResult::GetConfig(r_config),
                ) => config_manager.on_get_config_result(
                    pmc,
                    r_config,
                    reopen_sessions,
                    close_flag,
                    option_manager,
                    is_test_dc,
                    is_authorized,
                    is_bot,
                    main_dc_id,
                ),
                (
                    ConfigQuery::GetAppConfig { .. },
                    ConfigQueryResult::GetAppConfig(r_app_config),
                ) => config_manager.on_get_app_config_result(
                    pmc,
                    r_app_config,
                    close_flag,
                    option_manager,
                    is_authorized,
                    is_bot,
                ),
                (
                    ConfigQuery::GetContentSettings,
                    ConfigQueryResult::GetContentSettings(r_content_settings),
                ) => config_manager.on_get_content_settings_result(
                    r_content_settings,
                    option_manager,
                    is_bot,
                    close_flag,
                ),
                (
                    ConfigQuery::SetContentSettings { sensitive_enabled },
                    ConfigQueryResult::SetContentSettings(r_set),
                ) => config_manager.on_set_content_settings_result(
                    r_set,
                    sensitive_enabled,
                    option_manager,
                    is_bot,
                    close_flag,
                ),
                _ => {
                    tracing::error!("Mismatched config query result");
                    return;
                }
            }
        };
        self.apply_config_actions(actions);
    }

    /// M.3.8.2 — the net half of `ConfigManager::on_result`
    /// (ConfigManager.cpp:1040-1140): a completed `NetQuery` and its
    /// `actor_shared` link token reconstruct the dispatched query (the
    /// token↔request-constructor match is the C++ provenance the link
    /// token provides), decode via the `fetch_result` port, and feed the
    /// token dispatch above. Mismatched pairs warn and drop.
    pub(crate) fn on_config_net_query_result(&mut self, token: u64, net_query: NetQuery) {
        debug_assert!(net_query.is_ready(), "completion of an unanswered query");
        let Some(query) = config_result::reconstruct_config_query(token, &net_query) else {
            tracing::warn!(
                "Config query completion with token {token} does not match its request bytes"
            );
            return;
        };
        let mut net_query = net_query;
        let result = config_result::decode_config_query_result(&query, &mut net_query);
        self.on_config_query_result(query, result);
    }

    /// M.3.8.2 — drain the dispatcher's parked completions
    /// (token, NetQuery) in dispatch order; the close path runs this for
    /// the dispatcher-stop aborts, the actor flow once the callback
    /// delivery is wired there.
    pub(crate) fn drain_config_net_query_completions(&mut self) {
        let completions = std::mem::take(&mut *self.completed_config_queries.lock());
        for (token, net_query) in completions {
            self.on_config_net_query_result(token, net_query);
        }
    }

    /// Drain the UserManager's queued `updateUser`-class broadcasts (the
    /// C++ sends them straight to `Td::send_update` from the manager).
    /// The per-drive [`TdFileShared`] snapshot refresh (the C++ contexts
    /// read the same surfaces off `Td*`/`G()` at call time).
    pub(crate) fn refresh_file_shared(&mut self) {
        let is_bot = self.auth_manager.is_bot();
        let mut files_dir = String::new();
        let mut secure_files_dir = String::new();
        let mut use_storage_optimizer = false;
        let mut ignore_inline_thumbnails = false;
        let mut option_integers = BTreeMap::new();
        let mut database_paths = Vec::new();
        if self.global.has_db() {
            let (files_directory, database_directory) = {
                let db = self.global.td_db();
                database_paths = db.db_paths();
                (
                    db.parameters().files_directory.clone(),
                    db.parameters().database_directory.clone(),
                )
            };
            // `G()->get_files_dir()`/`get_secure_files_dir()`
            // (Global.cpp:149-155): the TdDb parameters, with the
            // store-all flag choosing the secure base
            files_dir = files_directory;
            let store_all = self
                .option_manager
                .as_ref()
                .map(|options| {
                    options.get_option_boolean("store_all_files_in_files_directory", false)
                })
                .unwrap_or(false);
            secure_files_dir = if store_all {
                files_dir.clone()
            } else {
                database_directory
            };
        }
        if let Some(options) = self.option_manager.as_ref() {
            use_storage_optimizer = options.get_option_boolean("use_storage_optimizer", false);
            ignore_inline_thumbnails =
                options.get_option_boolean("ignore_inline_thumbnails", false);
            for name in [
                "video_note_size_max",
                "storage_max_files_size",
                "storage_max_time_from_last_access",
                "storage_max_file_count",
                "storage_immunity_delay",
                "webfile_dc_id",
            ] {
                option_integers.insert(name.to_owned(), options.get_option_integer(name, 0));
            }
        }
        let ignore_file_names = self
            .option_manager
            .as_ref()
            .map(|options| options.get_option_boolean("ignore_file_names", false))
            .unwrap_or(false);
        self.file_shared.lock().refresh(TdFileSnapshot {
            files_dir,
            secure_files_dir,
            is_bot,
            use_message_database: self.use_message_database,
            use_file_database: self.use_file_database,
            use_storage_optimizer,
            ignore_inline_thumbnails,
            option_integers,
            unix_time: self.global.unix_time(),
            database_paths,
            is_test_dc: self.global.is_test_dc(),
            ignore_file_names,
        });
    }

    /// The files drive — the collapsed files-actor pump: refresh the
    /// shared snapshot, route the loader events into the FileManager,
    /// drain the outboxes, tick the DownloadManager counters. Runs once
    /// per actor turn (from [`Td::flush_user_updates`]), like the C++
    /// `send_closure` hops.
    pub(crate) fn drive_files(&mut self) {
        if self.state != State::Run {
            return;
        }
        self.refresh_file_shared();
        for _round in 0..64u32 {
            {
                let mut file_load_manager = self.file_load_manager.lock();
                file_load_manager.drive();
                if !file_load_manager.has_queued_events()
                    && !self.file_manager.lock().generate_has_events()
                {
                    // the generate callbacks queue independently of the
                    // loader (the external generation finishes with no
                    // loader events in flight) — the apply round must
                    // still drain them
                    break;
                }
            }
            let mut file_manager = self.file_manager.lock();
            let mut file_load_manager = self.file_load_manager.lock();
            file_manager.apply_load_events(&mut file_load_manager);
        }
        self.drain_file_shared();
        let now = self.global.unix_time();
        self.download_manager.lock().tick(f64::from(now));
    }

    /// The `StorageManager::timeout_expired` collapse (T.8,
    /// StorageManager.cpp:348-363): when the auto-gc window opens, run
    /// the gc with the default parameters and save the timestamp unless
    /// the pass aborted (the C++ skips the save on the 500 cancel).
    fn tick_storage_gc(&mut self) {
        let mut env = storage_env_fields(
            &mut self.global,
            &self.file_shared,
            self.option_manager.as_ref(),
        );
        let now = tdutils::time::system();
        if !self.storage_manager.auto_gc_due(&mut env, now) {
            return;
        }
        let parameters = FileGcParameters::from_options(&mut env, -1, -1, -1, -1);
        let mut gc_sink = TdFileGcSink(Arc::clone(&self.file_shared));
        let outcome = self
            .storage_manager
            .run_gc(&mut env, &mut gc_sink, parameters, false);
        // do not save the garbage collection timestamp if the request was
        // canceled (the 500 abort)
        if !matches!(&outcome, Err(status) if status.code() == 500) {
            self.storage_manager.save_last_gc_timestamp(&mut env, now);
        }
    }

    /// The StorageManager's deadline for the shared timeout slot (the C++
    /// `schedule_next_gc` arms its own actor timeout; the collapse parks
    /// at the window's upper bound and re-checks on fire).
    fn next_storage_gc_deadline(&mut self) -> Option<f64> {
        let use_storage_optimizer = self.file_shared.lock().use_storage_optimizer();
        self.storage_manager.next_gc_at(
            use_storage_optimizer,
            tdutils::time::system() as u32,
            tdutils::time::now(),
        )
    }

    /// The `getStorageStatistics` body over the storage env
    /// (Requests.cpp:2968-2979).
    pub(crate) fn get_storage_stats_object(
        &mut self,
        need_all_files: bool,
        dialog_limit: i32,
    ) -> td_api::StorageStatistics {
        let mut env = storage_env_fields(
            &mut self.global,
            &self.file_shared,
            self.option_manager.as_ref(),
        );
        self.storage_manager
            .get_storage_stats(&mut env, need_all_files, dialog_limit)
            .get_storage_statistics_object()
    }

    /// The `getStorageStatisticsFast` body (Requests.cpp:2981-2992).
    pub(crate) fn get_storage_stats_fast_object(&mut self) -> td_api::StorageStatisticsFast {
        let mut env = storage_env_fields(
            &mut self.global,
            &self.file_shared,
            self.option_manager.as_ref(),
        );
        self.storage_manager
            .get_storage_stats_fast(&mut env)
            .get_storage_statistics_fast_object()
    }

    /// The `getDatabaseStatistics` body (Requests.cpp:2994-3004).
    pub(crate) fn get_database_statistics_object(
        &mut self,
    ) -> Result<td_api::DatabaseStatistics, tdutils::status::Status> {
        let mut env = storage_env_fields(
            &mut self.global,
            &self.file_shared,
            self.option_manager.as_ref(),
        );
        self.storage_manager
            .get_database_stats(&mut env)
            .map(|stats| stats.get_database_statistics_object())
    }

    /// The `optimizeStorage` body (Requests.cpp:3006-3033): the
    /// `FileGcParameters` construction (the -1 sentinels read the
    /// `storage_*` options through the env) and the gc pass.
    pub(crate) fn optimize_storage(
        &mut self,
        request: td_api::optimizeStorage,
    ) -> Result<td_api::StorageStatistics, tdutils::status::Status> {
        let td_api::optimizeStorage {
            size,
            ttl,
            count,
            immunity_delay,
            file_types,
            chat_ids,
            exclude_chat_ids,
            return_deleted_file_statistics,
            chat_limit,
        } = request;
        let mut env = storage_env_fields(
            &mut self.global,
            &self.file_shared,
            self.option_manager.as_ref(),
        );
        let mut parameters =
            FileGcParameters::from_options(&mut env, size, ttl, count, immunity_delay);
        // the C++ rejects a null vector entry (Requests.cpp:3010-3012);
        // the generated model has no null FileType, so every entry maps
        for file_type in &file_types {
            parameters
                .file_types
                .push(crate::files::get_file_type(file_type));
        }
        parameters.owner_dialog_ids = chat_ids
            .iter()
            .map(|&chat_id| DialogId::new(chat_id))
            .collect();
        parameters.exclude_owner_dialog_ids = exclude_chat_ids
            .iter()
            .map(|&chat_id| DialogId::new(chat_id))
            .collect();
        parameters.dialog_limit = chat_limit;
        let mut gc_sink = TdFileGcSink(Arc::clone(&self.file_shared));
        self.storage_manager
            .run_gc(
                &mut env,
                &mut gc_sink,
                parameters,
                return_deleted_file_statistics,
            )
            .map(|stats| stats.get_storage_statistics_object())
    }

    /// The post-drive outbox drain — the `send_closure` hops land here,
    /// once per drive, in emission order.
    fn drain_file_shared(&mut self) {
        let updates = std::mem::take(&mut self.file_shared.lock().updates);
        for update in updates {
            self.send_update(update.into());
        }
        let new_file_events = std::mem::take(&mut self.file_shared.lock().new_file_events);
        for (size, real_size, cnt) in new_file_events {
            self.storage_manager.on_new_file(size, real_size, cnt);
        }
        let state_events =
            std::mem::take(&mut *self.file_shared.lock().download_state_events.lock());
        for (file_id, is_paused) in state_events {
            let (local_total_size, size, expected_size) = self
                .file_manager
                .lock()
                .get_file_view(file_id)
                .map(|view| {
                    (
                        view.local_total_size(),
                        view.size(),
                        view.expected_size(false),
                    )
                })
                .unwrap_or((0, 0, 0));
            // link_token 0: the C++ passes the actor token; the collapse
            // has no token-retry plane yet
            self.download_manager.lock().update_file_download_state(
                file_id,
                local_total_size,
                size,
                expected_size,
                is_paused,
                0,
            );
        }
        let user_download_finished =
            std::mem::take(&mut *self.file_shared.lock().user_download_finished_events.lock());
        for file_id in user_download_finished {
            self.file_manager
                .lock()
                .on_user_file_download_finished(file_id);
        }
        // the `UploadProfilePhotoCallback`/`UploadSavedMusicCallback`
        // hops — the `send_closure_later` re-entries of the C++ callbacks
        // (UserManager.cpp:2715-2741) replay here
        let profile_photo_uploads =
            std::mem::take(&mut *self.file_shared.lock().profile_photo_upload_events.lock());
        for event in profile_photo_uploads {
            self.run_profile_photo_upload_event(event);
        }
        let saved_music_uploads =
            std::mem::take(&mut *self.file_shared.lock().saved_music_upload_events.lock());
        for event in saved_music_uploads {
            self.run_saved_music_upload_event(event);
        }
        let worker_events = std::mem::take(&mut self.file_shared.lock().worker_events);
        let mut merge_events = Vec::new();
        if !worker_events.is_empty() {
            let mut file_manager = self.file_manager.lock();
            let mut file_load_manager = self.file_load_manager.lock();
            for event in worker_events {
                match event {
                    FileWorkerEvent::CancelDownload(node) => {
                        file_manager.replay_cancel_download(&node, &mut file_load_manager);
                    }
                    FileWorkerEvent::CancelUpload(node) => {
                        file_manager.replay_cancel_upload(&node, &mut file_load_manager);
                    }
                    FileWorkerEvent::CancelGenerate(node) => {
                        file_manager.replay_cancel_generate(&node, &mut file_load_manager);
                    }
                    FileWorkerEvent::FinishDownload(file_id) => {
                        file_manager.replay_finish_downloads(file_id);
                    }
                    FileWorkerEvent::FinishUpload(file_id) => {
                        file_manager.replay_finish_uploads(file_id, &mut file_load_manager);
                    }
                    FileWorkerEvent::RunNode(node) => {
                        file_manager.replay_run_node(&node, &mut file_load_manager);
                    }
                    FileWorkerEvent::MergeFiles(from_file_id, to_file_id) => {
                        merge_events.push((from_file_id, to_file_id));
                    }
                }
            }
        }
        for (from_file_id, to_file_id) in merge_events {
            self.file_reference_manager.merge(to_file_id, from_file_id);
        }
        let db_events = std::mem::take(&mut self.file_shared.lock().file_db_events);
        for event in db_events {
            self.apply_file_db_event(event);
        }
        self.flush_dlds();
    }

    /// One `UploadProfilePhotoCallback` hop — the C++
    /// `UserManager::on_upload_profile_photo[_error]` re-entry
    /// (UserManager.cpp:6145-6211): the ok continues over the file
    /// plane (the reupload ladder or the `UploadProfilePhotoQuery`
    /// send), the error fails the parked promise. The close gate keeps
    /// the entry parked, like the C++ early return.
    fn run_profile_photo_upload_event(&mut self, event: UserUploadEvent) {
        if self.global.close_flag() {
            return;
        }
        let mut user_manager = std::mem::take(&mut self.user_manager);
        match event {
            UserUploadEvent::Ok {
                file_upload_id,
                input_file,
            } => {
                let is_bot = self.auth_manager.is_bot();
                let Some(options) = self.option_manager.as_mut() else {
                    self.user_manager = user_manager;
                    return;
                };
                let env = crate::user_manager::UserEnv {
                    global: &mut self.global,
                    options,
                    auth_is_bot: is_bot,
                };
                let mut files = self.file_manager.lock();
                let mut fllm = self.file_load_manager.lock();
                let upload_callback = self.profile_photo_upload_callback.clone();
                user_manager.on_upload_profile_photo(
                    crate::user_manager::SetProfilePhotoTd {
                        env: &env,
                        files: &mut files,
                        fllm: &mut fllm,
                        upload_callback: &upload_callback,
                        stickers: &self.stickers_manager,
                    },
                    file_upload_id,
                    input_file,
                );
            }
            UserUploadEvent::Error {
                file_upload_id,
                status,
            } => {
                user_manager.on_upload_profile_photo_error(file_upload_id, status);
            }
        }
        self.user_manager = user_manager;
    }

    /// One `UploadSavedMusicCallback` hop — the C++
    /// `UserManager::on_upload_saved_music[_error]` re-entry
    /// (UserManager.cpp:7230-7261): the ok resolves the audios input
    /// media (the env locks the file manager, so it runs before the
    /// manager tail takes the borrow) and continues in
    /// `do_upload_saved_music`.
    fn run_saved_music_upload_event(&mut self, event: UserUploadEvent) {
        if self.global.close_flag() {
            return;
        }
        let mut user_manager = std::mem::take(&mut self.user_manager);
        match event {
            UserUploadEvent::Ok {
                file_upload_id,
                input_file,
            } => {
                tdutils::log_info!("Profile audio {file_upload_id:?} has been uploaded");
                let had_input_file = input_file.is_some();
                let promise = user_manager.take_saved_music_upload_promise(file_upload_id);
                let input_media = self
                    .audios_manager
                    .get_input_media(self, file_upload_id.file_id, input_file, None)
                    .expect("CHECK(input_media != nullptr)");
                let mut files = self.file_manager.lock();
                let mut fllm = self.file_load_manager.lock();
                user_manager.do_upload_saved_music(
                    self.global.close_flag(),
                    &mut files,
                    &mut fllm,
                    file_upload_id,
                    had_input_file,
                    input_media,
                    promise,
                );
            }
            UserUploadEvent::Error {
                file_upload_id,
                status,
            } => {
                user_manager.on_upload_saved_music_error(file_upload_id, status);
            }
        }
        self.user_manager = user_manager;
    }

    /// The file-db replay: build the node's `FileData` (the C++
    /// `try_flush_node_info`/`try_flush_node_full` bodies) and run it
    /// through the `FileDb` gate over TdDb's "files" kv.
    fn apply_file_db_event(&mut self, event: FileDbEvent) {
        match event {
            FileDbEvent::Flush {
                node,
                other_pmc_id,
                new_remote,
                new_local,
                new_generate,
            } => {
                let data = self.node_file_data(&node);
                let mut file_db = FileDb::new(self.global.td_db().files_kv());
                file_db.set_file_data(
                    self.global.td_db().files_kv(),
                    node.pmc_id(),
                    &data,
                    new_remote,
                    new_local,
                    new_generate,
                    &mut self.file_reference_manager,
                );
                // the merge-counter drop of `try_flush_node_full`
                if other_pmc_id.is_valid() && other_pmc_id != node.pmc_id() {
                    file_db.clear_file_data(self.global.td_db().files_kv(), other_pmc_id, &data);
                }
            }
            FileDbEvent::Clear { node } => {
                let data = self.node_file_data(&node);
                let mut file_db = FileDb::new(self.global.td_db().files_kv());
                file_db.clear_file_data(self.global.td_db().files_kv(), node.pmc_id(), &data);
            }
        }
    }

    /// The `FileData` construction from a node (`try_flush_node_info`,
    /// FileManager.cpp) — the file sources ride the
    /// `FileReferenceManager` (its `FileSourceStorage` impl).
    fn node_file_data(&self, node: &FileNode) -> FileData {
        node.to_file_data(
            self.file_reference_manager
                .get_some_file_sources(node.main_file_id()),
        )
    }

    /// The `dlds#` pmc flush — gated on the T.7 record-layout unification
    /// (the D1 warning: no raw-i32 records reach the real pmc).
    fn flush_dlds(&mut self) {
        if !self.file_shared.lock().dlds_pmc_live {
            return;
        }
        let (current, saved) = {
            let shared = self.file_shared.lock();
            (shared.dlds.clone(), shared.dlds_saved.clone())
        };
        let keys: BTreeSet<_> = saved.keys().chain(current.keys()).collect();
        {
            let pmc = self.global.binlog_pmc();
            for key in keys {
                match (current.get(key), saved.get(key)) {
                    (Some(value), Some(old)) if value == old => {}
                    (Some(value), _) => {
                        pmc.set_raw(key.as_bytes(), value);
                    }
                    (None, Some(_)) => {
                        pmc.erase(key);
                    }
                    (None, None) => {}
                }
            }
        }
        self.file_shared.lock().dlds_saved = current;
    }

    /// Drain the managers' queued update broadcasts (the C++ sends them
    /// straight to `Td::send_update` from the managers).
    pub(crate) fn flush_user_updates(&mut self) {
        self.drive_files();
        for update in self.user_manager.take_updates() {
            self.send_update(update.into());
        }
        for update in self.chat_manager.take_updates() {
            self.send_update(update.into());
        }
        let notification_updates = std::mem::take(&mut self.notification_updates);
        for update in notification_updates {
            self.send_update(update.into());
        }
        let sponsored_updates = std::mem::take(&mut self.sponsored_updates);
        for update in sponsored_updates {
            self.send_update(update.into());
        }
        let language_pack_updates = std::mem::take(&mut self.language_pack_updates);
        for update in language_pack_updates {
            self.send_update(update.into());
        }
        let animations_updates = std::mem::take(&mut self.animations_updates);
        for update in animations_updates {
            self.send_update(update.into());
        }
        let reaction_updates = std::mem::take(&mut self.reaction_updates);
        for update in reaction_updates {
            self.send_update(update.into());
        }
        let star_updates = std::mem::take(&mut self.star_updates);
        for update in star_updates {
            self.send_update(update.into());
        }
    }

    /// `AnimationsManager::AnimationsManager`
    /// (AnimationsManager.cpp:127-147) plus the `start_up` halves — the
    /// collapsed actor start reads the options and the `ans` pmc record
    /// (M.20).
    fn init_animations_manager(&mut self) {
        let mut env = TdAnimationsEnv {
            global: &mut self.global,
            options: self.option_manager.as_mut(),
            auth_is_bot: self.auth_manager.is_bot(),
            file_manager: Arc::clone(&self.file_manager),
            file_reference_manager: &mut self.file_reference_manager,
            updates: &mut self.animations_updates,
        };
        self.animations_manager.init(&mut env);
        let inline_updates = std::mem::take(&mut self.inline_updates);
        for update in inline_updates {
            self.send_update(update.into());
        }
        let message_query_updates = std::mem::take(&mut self.message_query_updates);
        for update in message_query_updates {
            self.send_update(update.into());
        }
        let poll_updates = std::mem::take(&mut self.poll_updates);
        for update in poll_updates {
            self.send_update(update.into());
        }
        let account_updates = std::mem::take(&mut self.account_updates);
        for update in account_updates {
            self.send_update(update.into());
        }
        let theme_updates = std::mem::take(&mut self.theme_updates);
        for update in theme_updates {
            self.send_update(update.into());
        }
    }

    /// `BackgroundManager::start_up` (BackgroundManager.cpp:396-474; the
    /// manager constructed at Td.cpp:1169-1171) — idempotent; the manager
    /// no-ops for bots and loads the persisted selected/local backgrounds
    /// otherwise.
    fn init_background_manager(&mut self) {
        let mut manager = std::mem::take(&mut self.background_manager);
        {
            let mut env = BackgroundEnv { td: self };
            manager.init(&mut env);
        }
        self.background_manager = manager;
        let background_updates = std::mem::take(&mut self.background_updates);
        for update in background_updates {
            self.send_update(update.into());
        }
    }

