    /// The deferred-response outbox drain — the `send_closure(td_id_,
    /// &Td::send_result/send_error, id, ...)` hop the C++ request promises
    /// make when a manager completes them (possibly from inside another
    /// manager call, where a `&mut Td` is not available).
    pub(crate) fn flush_deferred_results(&mut self) {
        let deferred = {
            let mut guard = self.deferred_results.lock();
            std::mem::take(&mut *guard)
        };
        for (id, result) in deferred {
            match result {
                Ok(object) => self.send_result(id, object),
                Err(status) => self.send_error_impl(id, status.code(), status.message()),
            }
        }
    }

    /// The promise factory for the request layer: a manager-completed
    /// `Result` lands in the outbox under the request id.
    pub(crate) fn deferred_promise<T, F>(&self, id: u64, map: F) -> tdutils::promise::Promise<T>
    where
        T: Send + 'static,
        F: FnOnce(T) -> Object + Send + 'static,
    {
        let outbox = Arc::clone(&self.deferred_results);
        tdutils::promise::PromiseCreator::lambda_result(
            move |result: tdutils::status::Result<T>| {
                let result = match result {
                    tdutils::status::Result::Ok(value) => Ok(map(value)),
                    tdutils::status::Result::Err(status) => Err(status),
                };
                outbox.lock().push((id, result));
            },
        )
    }

    /// Point the actor timeout at the earliest armed deadline (the member
    /// MultiTimeouts re-arm on every set/cancel). The slot is shared with
    /// the ConfigManager expire time and the recoverer wakeup, so this
    /// mirrors into `sync_config_timeout` — a no-op outside a scheduler,
    /// like the other direct-call mirroring points.
    fn rearm_user_timeouts(&mut self) {
        self.sync_config_timeout();
    }

    /// `Td::send_result` (Td.cpp:1399-1414).
    pub(crate) fn send_result(&mut self, id: u64, object: Object) {
        if id == 0 {
            tracing::error!("Sending a result through send_result with id 0");
            return;
        }

        if self.request_set.remove(&id) {
            // Td.cpp:1410 — the td_requests result log (pretty form).
            tdutils::vlog!(
                tdutils::logging::verbosity::TD_REQUESTS,
                "td_requests",
                at "Td.cpp",
                1410,
                "Sending result for request {}: {}",
                id,
                object.to_debug_string()
            );
            let Some(callback) = self.callback.as_mut() else {
                return;
            };
            callback.on_result(id, object);
        }
    }

    /// `Td::send_error_impl` (Td.cpp:1416-1428).
    pub(crate) fn send_error_impl(&mut self, id: u64, code: i32, message: &str) {
        if self.request_set.remove(&id) {
            if code == 0 && message == "Lost promise" {
                panic!(
                    "Lost promise for query {id} in close state {}",
                    self.close_flag
                );
            }
            // Td.cpp:1424 — the td_requests error log (oneline).
            tdutils::vlog!(
                tdutils::logging::verbosity::TD_REQUESTS,
                "td_requests",
                at "Td.cpp",
                1424,
                "Sending error for request {}: {}",
                id,
                oneline(
                    &td_api::Error {
                        code,
                        message: message.to_string(),
                    }
                    .to_debug_string()
                )
            );
            let Some(callback) = self.callback.as_mut() else {
                return;
            };
            callback.on_error(
                id,
                td_api::Error {
                    code,
                    message: message.to_string(),
                },
            );
        }
    }

    /// `Td::get_parameters` (Td.cpp:1435-1497): validate + split into the
    /// `Td::Parameters` and the `TdDb::Parameters`.
    fn get_parameters(
        &mut self,
        p: td_api::setTdlibParameters,
    ) -> Result<(Parameters, DbParameters), td_api::Error> {
        let error = |code: i32, message: &str| td_api::Error {
            code,
            message: message.to_string(),
        };

        let td_api::setTdlibParameters {
            use_test_dc,
            database_directory,
            files_directory,
            database_encryption_key,
            use_file_database,
            use_chat_info_database,
            use_message_database,
            use_secret_chats,
            api_id,
            api_hash,
            system_language_code,
            device_model,
            system_version,
            application_version,
        } = p;

        // The C++ clean_input_string checks byte-level UTF-8 (impossible to
        // violate in Rust Strings) and sanitizes control characters — the
        // sanitization is observable on the stored values.
        let clean = |s: &str| -> Result<String, td_api::Error> {
            crate::misc::clean_input_string(s)
                .ok_or_else(|| error(400, "Strings must be encoded in UTF-8"))
        };
        let api_hash = clean(&api_hash)?;
        let system_language_code = clean(&system_language_code)?;
        let device_model = clean(&device_model)?;
        let system_version = clean(&system_version)?;
        let application_version = clean(&application_version)?;

        if api_id <= 0 {
            return Err(error(
                400,
                "Valid api_id must be provided. Can be obtained at https://my.telegram.org",
            ));
        }
        if api_hash.is_empty() {
            return Err(error(
                400,
                "Valid api_hash must be provided. Can be obtained at https://my.telegram.org",
            ));
        }

        let parameters = Parameters {
            api_id,
            api_hash: api_hash.clone(),
            use_secret_chats,
            use_test_dc,
            database_directory: PathBuf::from(&database_directory),
        };
        let db_parameters = DbParameters {
            // `TdDb::as_db_key` (TdDb.cpp:671-676, via Td.cpp:1457): the key
            // arrives base64-decoded and is ALWAYS a raw key — the KDF fast
            // path (2 iterations), never the password path — with the empty
            // key defaulting to the well-known "cucumber" raw key, so the
            // binlog is always AesCtr-encrypted.
            encryption_key: crate::requests::as_db_key(database_encryption_key),
            database_directory,
            files_directory,
            is_test_dc: use_test_dc,
            use_file_database,
            use_chat_info_database,
            use_message_database,
        };

        // Create MtprotoHeader::Options (Td.cpp:1465-1494).
        let header = &mut self.header_options;
        header.api_id = api_id;
        header.system_language_code = trim_ascii(&system_language_code).to_owned();
        header.device_model = trim_ascii(&device_model).to_owned();
        header.system_version = trim_ascii(&system_version).to_owned();
        header.application_version = trim_ascii(&application_version).to_owned();
        if header.system_language_code.is_empty() {
            return Err(error(400, "System language code must be non-empty"));
        }
        if header.device_model.is_empty() {
            return Err(error(400, "Device model must be non-empty"));
        }
        if header.system_version.is_empty() {
            header.system_version = get_operating_system_version();
        }
        if header.application_version.is_empty() {
            return Err(error(400, "Application version must be non-empty"));
        }
        if header.api_id != 21724 {
            header.application_version += ", TDLib ";
            header.application_version += crate::option_manager::API_VERSION;
        }
        header.language_pack = String::new();
        header.language_code = String::new();
        header.parameters = String::new();
        header.is_emulator = false;

        Ok((parameters, db_parameters))
    }

    /// `Td::start_up` (Td.cpp:438-461): the endianness guard is a compile
    /// error here; the common state + the fake auth state follow.
    fn emit_start_up(&mut self) {
        // The UpdatesManager bridge — the C++ externally-owned manager
        // actor (`Td.cpp:1319-1321`): registered in start_up, under this
        // actor, so the `send_closure`-routed UM entries run in the
        // manager's slices with its context tag.
        let td_ptr: *mut Td = self;
        let me = self.actor_id();
        self.updates_manager_bridge = Scheduler::instance().create_bridge_actor(
            "UpdatesManager",
            UmBridge { td: td_ptr },
            &me,
        );
        // The Requests instance and the Global are plain Rust structures —
        // no actor creation needed (the C++ actor bookkeeping in start_up
        // guards its async teardown).
        for update in self.get_fake_current_state() {
            self.send_update(update);
        }
    }

    // --------------------------------------------------------------------
    // The walking-skeleton live paths (the auth-net slice + the messaging
    // queries over the NetQueryDispatcher).
    // --------------------------------------------------------------------

    /// The `api_id`/`api_hash` pair for the auth queries.
    fn auth_params(&self) -> (i32, String) {
        let parameters = self.parameters.as_ref().expect("parameters");
        (parameters.api_id, parameters.api_hash.clone())
    }

    /// Allocate a dispatch token and park the request.
    fn park_net(&mut self, request_id: u64, kind: PendingNetKind) -> u64 {
        let token = self.net_dispatch_token;
        self.net_dispatch_token += 1;
        self.pending_net.insert(token, (request_id, kind));
        token
    }

    /// Serialize + dispatch one walking-skeleton query (the session
    /// prepends the shared `MtprotoHeader`).
    fn dispatch_walking_query(
        &mut self,
        token: u64,
        function: telegram_api::Function,
        auth_flag: AuthFlag,
    ) {
        let mut bytes = Vec::new();
        function.store(&mut bytes);
        let tl_constructor = i32::from_le_bytes(bytes[0..4].try_into().unwrap());
        let dispatcher = self
            .net_query_dispatcher
            .as_ref()
            .expect("the net dispatcher exists");
        let net_query = NetQuery::new(
            token,
            DcId::main(),
            NetQueryType::Common,
            auth_flag,
            GzipFlag::Off,
            tl_constructor,
            bytes,
            u32::MAX,
            60 * 60 * 24,
        );
        let callback = NetDispatchCallback {
            token,
            completed: self.net_completed.clone(),
            shared: self.net_shared.clone(),
        };
        dispatcher.dispatch_with_callback(net_query, Box::new(callback));
    }

    /// Dispatch a prepared `AuthNetQuery` and park the request.
    fn dispatch_auth(
        &mut self,
        request_id: u64,
        kind: AuthPendingKind,
        query: &crate::auth_manager::AuthNetQuery,
    ) {
        let (api_id, api_hash) = self.auth_params();
        let function = build_auth_net_function(query, api_id, &api_hash);
        let token = self.park_net(request_id, PendingNetKind::Auth(kind));
        self.dispatch_walking_query(token, function, AuthFlag::Off);
    }

    /// `setAuthenticationPhoneNumber` (Requests.cpp:1786-1794): the clean
    /// check, then `AuthManager::set_phone_number` over the dispatcher —
    /// the request parks until the `auth.sendCode` answer applies.
    pub(crate) fn set_authentication_phone_number(&mut self, request_id: u64, phone: String) {
        let phone = match crate::misc::clean_input_string(&phone) {
            Some(phone) => phone,
            None => {
                return self.send_error_impl(request_id, 400, "Strings must be encoded in UTF-8");
            }
        };
        match self.auth_manager.prepare_authentication_phone_number(phone) {
            Ok(query) => {
                self.dispatch_auth(request_id, AuthPendingKind::SendCode, &query);
            }
            Err(message) => self.send_error_impl(request_id, 400, &message),
        }
    }

    pub(crate) fn check_authentication_bot_token(&mut self, request_id: u64, token: String) {
        let token = match crate::misc::clean_input_string(&token) {
            Some(token) => token,
            None => {
                return self.send_error_impl(request_id, 400, "Strings must be encoded in UTF-8");
            }
        };
        match self
            .auth_manager
            .prepare_check_authentication_bot_token(token)
        {
            Ok(query) => {
                self.dispatch_auth(request_id, AuthPendingKind::BotToken, &query);
            }
            Err(message) => self.send_error_impl(request_id, 400, &message),
        }
    }

    pub(crate) fn check_authentication_code(&mut self, request_id: u64, code: String) {
        let code = match crate::misc::clean_input_string(&code) {
            Some(code) => code,
            None => {
                return self.send_error_impl(request_id, 400, "Strings must be encoded in UTF-8");
            }
        };
        match self.auth_manager.prepare_check_authentication_code(code) {
            Ok(query) => {
                self.dispatch_auth(request_id, AuthPendingKind::SignIn, &query);
            }
            Err(message) => self.send_error_impl(request_id, 400, &message),
        }
    }

    /// `logOut` (Requests.cpp:1795-1805 + `AuthManager::log_out` over the
    /// dispatcher).
    pub(crate) fn log_out(&mut self, request_id: u64) {
        match self.auth_manager.prepare_log_out() {
            Ok(Some(query)) => {
                self.dispatch_auth(request_id, AuthPendingKind::LogOut, &query);
            }
            Ok(None) => {
                // The destroy path without a network round-trip.
                self.flush_auth_updates();
                self.send_result(request_id, ok_object());
            }
            Err(message) => self.send_error_impl(request_id, 400, &message),
        }
    }

    pub(crate) fn check_authentication_password(&mut self, request_id: u64, password: String) {
        let password = match crate::misc::clean_input_string(&password) {
            Some(password) => password,
            None => {
                return self.send_error_impl(request_id, 400, "Strings must be encoded in UTF-8");
            }
        };
        match self
            .auth_manager
            .prepare_check_authentication_password(password.clone())
        {
            Ok(query) => {
                self.dispatch_auth(
                    request_id,
                    AuthPendingKind::CheckPassword { password },
                    &query,
                );
            }
            Err(message) => self.send_error_impl(request_id, 400, &message),
        }
    }

    // ------------------------------------------------------------------
    // The PhoneNumberManager plane (the auth-tails glue slice). The five
    // entry points follow the `set_authentication_phone_number` shape:
    // prepare in the manager → park + dispatch the real query → the
    // answer applies on the drain ([`Td::on_phone_answer`]).
    // ------------------------------------------------------------------

    /// `sendPhoneNumberCode` (Requests.cpp:2480-2486 →
    /// `PhoneNumberManager::set_phone_number`). The ChangePhone arm hides
    /// the `CheckPhoneNumber` suggested action between the validation and
    /// the query (PhoneNumberManager.cpp:250-251).
    pub(crate) fn send_phone_number_code(
        &mut self,
        request_id: u64,
        phone_number: String,
        settings: Option<&td_api::PhoneNumberAuthenticationSettings>,
        ty: Option<&td_api::PhoneNumberCodeType>,
    ) {
        let prepared =
            match self
                .phone_number_manager
                .prepare_set_phone_number(phone_number, settings, ty)
            {
                std::result::Result::Ok(prepared) => prepared,
                std::result::Result::Err(status) => {
                    return self.send_error_impl(request_id, status.code(), status.message());
                }
            };
        if prepared.hide_check_phone_number {
            let mut action = crate::suggested_action::SuggestedAction::default();
            action.init(crate::suggested_action::SuggestedActionType::CheckPhoneNumber);
            let mut env = AccountEnv {
                global: &mut self.global,
                options: self.option_manager.as_mut(),
                user_manager: &mut self.user_manager,
                device_token_manager: &mut self.device_token_manager,
                auth_is_bot: self.auth_manager.is_bot(),
                updates: &mut self.account_updates,
                net: None,
            };
            self.suggested_action_manager
                .hide_suggested_action(&mut env, action);
        }
        let token = self.park_net(
            request_id,
            PendingNetKind::Phone(PhonePendingKind::SendCode {
                generation: prepared.generation,
            }),
        );
        self.dispatch_walking_query(token, prepared.function, AuthFlag::On);
    }

    /// `sendPhoneNumberFirebaseSms` (Requests.cpp:2488-2493 →
    /// `PhoneNumberManager::send_firebase_sms`).
