/// The [`FileLoadNetFactory`] over the live bridge-backed nets.
pub(crate) struct TdFileLoadNetFactory {
    cell: Arc<parking_lot::Mutex<LiveNetCell>>,
}

impl TdFileLoadNetFactory {
    pub(crate) fn new() -> TdFileLoadNetFactory {
        TdFileLoadNetFactory {
            cell: Arc::new(parking_lot::Mutex::new(LiveNetCell::default())),
        }
    }

    /// Fills the cell once the dispatcher exists (Td `init`).
    pub(crate) fn install(
        &self,
        dispatcher: Arc<NetQueryDispatcher>,
        shared: Arc<parking_lot::Mutex<TdFileShared>>,
    ) {
        self.cell.lock().install(dispatcher, shared);
    }
}

impl FileLoadNetFactory for TdFileLoadNetFactory {
    fn download_net(&mut self) -> Box<dyn FileDownloaderNet> {
        Box::new(LiveDownloadNet {
            cell: Arc::clone(&self.cell),
        })
    }

    fn upload_net(&mut self) -> Box<dyn FileUploaderNet> {
        Box::new(LiveUploadNet {
            cell: Arc::clone(&self.cell),
        })
    }

    fn hash_net(&mut self) -> Box<dyn FileHashUploaderNet> {
        Box::new(LiveHashNet {
            cell: Arc::clone(&self.cell),
        })
    }

    fn utils_net(&mut self) -> Box<dyn FileDownloaderNet> {
        self.download_net()
    }
}

/// Parses a top-level boxed `Vector<user>` (the `users.getUsers` result).
fn parse_vector_premium_gift_code_option(
    data: &[u8],
) -> Option<Vec<telegram_api::PremiumGiftCodeOption>> {
    let mut reader = telegram_api::tl::Reader::new(data);
    if reader.i32().ok()? != telegram_api::tl::VECTOR_ID {
        return None;
    }
    let count = reader.i32().ok()? as u32 as usize;
    let mut options = Vec::with_capacity(count);
    for _ in 0..count {
        options.push(telegram_api::PremiumGiftCodeOption::read(&mut reader).ok()?);
    }
    Some(options)
}

fn parse_vector_user(data: &[u8]) -> Option<Vec<telegram_api::user>> {
    let mut reader = telegram_api::tl::Reader::new(data);
    if reader.i32().ok()? != telegram_api::tl::VECTOR_ID {
        return None;
    }
    let count = reader.i32().ok()? as u32 as usize;
    let mut users = Vec::with_capacity(count);
    for _ in 0..count {
        if let telegram_api::User::user(user) = telegram_api::User::read(&mut reader).ok()? {
            users.push(user);
        }
    }
    Some(users)
}

/// The `UpdatesManager` bridge actor — the Rust port of the C++
/// externally-owned manager registration (`Td.cpp:1320`
/// `register_actor("UpdatesManager", updates_manager_.get())`).
///
/// C++ gives each manager a second actor identity around the very same
/// object: `send_closure`-routed entries land in the manager's own
/// mailbox and run in a scheduler slice whose log context is the
/// manager's (`[!UpdatesManager]`), while direct `td_->updates_manager_->`
/// calls stay in the caller's context. The bridge reproduces exactly
/// that: a fully normal actor (own mailbox, own Start slice, own
/// `Add to mailbox`/`Start run actor`/`Run mailbox` trace lines) whose
/// handlers reach the owner `Td` through a raw pointer, the way the C++
/// manager reaches it through `td_`.
///
/// The exclusivity that C++ gets for free (distinct objects) is
/// mechanical here: the scheduler's owner-link guard
/// ([`tdactor::Scheduler::create_bridge_actor`]) never dispatches the
/// bridge and its owner in the same frame — sends that would re-enter
/// the pair take the mailbox instead.
pub(crate) struct UmBridge {
    /// The owning Td actor. Created us; we are destroyed synchronously
    /// in its `tear_down` (the C++ `reset_actor` order), so the pointer
    /// is valid for every deref. Dereferenced only inside our dispatch
    /// slices, which the owner-link guard keeps exclusive with the
    /// owner's.
    td: *mut Td,
}

impl Actor for UmBridge {
    /// `UpdatesManager::start_up` (UpdatesManager.cpp:284).
    fn start_up(&mut self) {
        // SAFETY: the owner-link exclusivity contract — no owner borrow
        // is live inside a bridge slice.
        unsafe { (*self.td).um_start_up() }
    }

    /// `UpdatesManager::hangup` (cpp:305-313): drop the pending update
    /// backlog, then stop.
    fn hangup(&mut self) {
        // SAFETY: see `start_up`.
        unsafe { (*self.td).um_hangup() };
        self.stop();
    }
}

impl UmBridge {
    /// The mailbox dispatch arm: run one message against the owner.
    fn run(&mut self, message: UmMessage) {
        // SAFETY: see `start_up`.
        let td = unsafe { &mut *self.td };
        message.run(td);
    }
}

// SAFETY: the raw owner pointer is dereferenced only inside the bridge's
// dispatch slices, which the scheduler's owner-link guard keeps exclusive
// with the owner's own dispatch; the owner destroys the bridge (and so
// outlives every deref) in its `tear_down`. The pointer itself crosses
// threads only inside queued events on the owner's scheduler — the same
// single-scheduler contract as every actor id.
unsafe impl Send for UmBridge {}

/// One `send_closure`-class entry into the UpdatesManager — the payloads
/// of the C++ hops (`send_closure(G()->updates_manager(), ...)`) that run
/// in the manager's context. The C++ direct entries
/// (`get_difference`, `schedule_get_difference`,
/// `on_update_from_auth_key_id`, the `add_pending_pts_update` call sites)
/// do not ride this enum; they stay direct calls, in the caller's
/// context, like the C++.
pub(crate) enum UmMessage {
    /// `on_get_updates` — the public entry's
    /// `send_closure_later(actor_id(this), ...)` self-bounce
    /// (UpdatesManager.cpp:1176-1178): always a separate slice.
    OnGetUpdates {
        updates: Box<telegram_api::Updates>,
        promise: Promise<()>,
    },
    /// `on_get_updates` + the migrate tail — the C++
    /// `PromiseCreator::lambda` chain of `migrate_dialog_to_megagroup`
    /// (DialogManager.cpp:1768-1775): the Updates run through the engine,
    /// then `on_migrate_chat_to_megagroup` completes the object promise
    /// (the lambda's `send_closure` hop collapses onto the run slice).
    OnGetUpdatesMigrateChat {
        updates: Box<telegram_api::Updates>,
        chat_id: crate::chat_manager::ChatId,
        promise: Promise<crate::td_api::Object>,
    },
    /// `on_get_updates` + the channel-toggle intake tail — the C++
    /// `PromiseCreator::lambda` chains of the ChatManager toggle
    /// families (ChatManager.cpp:756, :807, :903, :954, :1232): the
    /// Updates run through the engine, then the intake completes the
    /// promise (the LambdaPromise runs on both the ok and the error
    /// paths — the `do_error(Auto())` shape — so the tail always
    /// follows the updates engine).
    OnGetUpdatesChannelToggle {
        updates: Box<telegram_api::Updates>,
        tail: crate::chat_manager::ChatToggleTail,
        promise: Promise<()>,
    },
    /// `on_get_updates` + the story-core intake tail — the C++
    /// `PromiseCreator::lambda` chains of the StoryManager answer
    /// halves (StoryManager.cpp:3485, :2945, :1400, :1604): the Updates
    /// run through the engine, then the tail runs the manager intake
    /// (the parked promises settle there).
    OnGetUpdatesStoryTail {
        updates: Box<telegram_api::Updates>,
        tail: crate::story_manager::StoryNetTail,
    },
    /// `on_get_updates` + the paid-reaction chain tail — the C++
    /// `PromiseCreator::lambda` chain of
    /// `MessagesManager::commit_paid_message_reactions`
    /// (MessagesManager.cpp:20433-20439): the Updates run through the
    /// engine, then the chain result completes
    /// `on_set_message_reactions` with the request promise (the lambda
    /// runs on both the ok and the error paths — the exact C++ order).
    OnGetUpdatesPaidReaction {
        updates: Box<telegram_api::Updates>,
        message_full_id: crate::messages_manager::MessageFullId,
        promise: Promise<()>,
    },
    /// `on_get_difference` / the shared `GetPtsUpdate` parse arm
    /// (cpp:522, :364).
    OnGetDifference {
        difference: telegram_api::updates_Difference,
    },
    /// `on_failed_get_difference` (cpp:524).
    OnFailedGetDifference { error: Status },
    /// `on_get_updates_state` (cpp:1875).
    OnGetUpdatesState { state: telegram_api::updates_State },
    /// `on_failed_get_updates_state` (cpp:1878).
    OnFailedGetUpdatesState { error: Status },
    /// `on_server_pong` (cpp:1934).
    OnServerPong {
        state: Option<telegram_api::updates_State>,
    },
    /// The timeout fixpoint — the C++ AlarmTimeout hops
    /// (`retry_timeout_`/`ping_timeout_`/the save timers wake the
    /// manager's slice; the `Timeout`-event machinery itself is the
    /// later timeout-actor step).
    TickTimeouts,
}

impl UmMessage {
    /// Run the entry against the owner — the env is built exactly like
    /// the C++ manager reads its `td_` world, and the sink drains
    /// afterwards (the C++ sends updates to the client synchronously
    /// inside the slice; the drain flush is the sink's batching
    /// boundary).
    fn run(self, td: &mut Td) {
        match self {
            UmMessage::OnGetUpdates { updates, promise } => {
                td.with_updates_env(|um, env| um.on_get_updates(env, *updates, promise));
            }
            UmMessage::OnGetUpdatesPaidReaction {
                updates,
                message_full_id,
                promise,
            } => {
                // the chain's promise captures the engine result — the
                // `unit_slot_promise` shape (the updates engine completes
                // it synchronously; the slot carries the result into
                // `on_set_message_reactions`'s need_reload band)
                let slot: std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<()>>>> =
                    std::sync::Arc::new(std::sync::Mutex::new(None));
                let capture = std::sync::Arc::clone(&slot);
                let updates_promise =
                    tdutils::promise::PromiseCreator::lambda_result(move |result| {
                        *capture.lock().unwrap() = Some(result);
                    });
                td.with_updates_env(|um, env| um.on_get_updates(env, *updates, updates_promise));
                let result = slot
                    .lock()
                    .unwrap()
                    .take()
                    .unwrap_or(tdutils::status::Result::Ok(()));
                td.on_set_message_reactions_chain(message_full_id, result, promise);
            }
            UmMessage::OnGetUpdatesMigrateChat {
                updates,
                chat_id,
                promise,
            } => {
                // the empty promise stands in for the C++ `Promise<Unit>`
                // the handler passes to `on_get_updates` — the chain's
                // only continuation is the tail below
                td.with_updates_env(|um, env| um.on_get_updates(env, *updates, Promise::default()));
                // the C++ ordering guarantee is the actor mailbox: the
                // sink's chats intake was queued before the lambda's
                // `on_migrate_chat_to_megagroup` hop, so the drain runs
                // between them here
                td.drain_sink();
                crate::dialog_manager::on_migrate_chat_to_megagroup(td, chat_id, promise);
            }
            UmMessage::OnGetUpdatesChannelToggle {
                updates,
                tail,
                promise,
            } => {
                // the empty promise stands in for the C++ `Promise<Unit>`
                // the handler passes to `on_get_updates` — the lambda
                // chain's only continuation is the intake tail below
                td.with_updates_env(|um, env| um.on_get_updates(env, *updates, Promise::default()));
                td.drain_sink();
                td.with_chat_intake(|chat_manager, user_manager, env| {
                    tail.run(chat_manager, user_manager, env, promise);
                });
            }
            UmMessage::OnGetUpdatesStoryTail { updates, tail } => {
                // the empty promise stands in for the C++ `Promise<Unit>`
                // the handler passes to `on_get_updates` — the lambda
                // chain's only continuation is the intake tail below
                td.with_updates_env(|um, env| um.on_get_updates(env, *updates, Promise::default()));
                td.drain_sink();
                use crate::story_manager::StoryNetTail;
                match tail {
                    StoryNetTail::SetStoryReaction { story_full_id } => {
                        td.with_story_manager(|env, manager| {
                            manager.on_set_story_reaction(
                                env,
                                story_full_id,
                                tdutils::status::Result::Ok(()),
                            );
                        });
                    }
                    StoryNetTail::SendStory => {
                        // cpp:1400-1408 — the pending story's Ok tail
                        if let Some(pending_story) = td.story_manager.take_send_story_tail() {
                            td.with_story_manager(|env, manager| {
                                manager.delete_pending_story(env, pending_story, Status::ok());
                            });
                        }
                    }
                    StoryNetTail::EditStory { story_full_id } => {
                        td.with_story_manager(|env, manager| {
                            manager.on_edit_story(
                                env,
                                story_full_id,
                                tdutils::status::Result::Ok(()),
                            );
                        });
                    }
                }
            }
            UmMessage::OnGetDifference { difference } => {
                td.with_updates_env(|um, env| um.on_get_difference(env, difference));
            }
            UmMessage::OnFailedGetDifference { error } => {
                td.with_updates_env(|um, env| um.on_failed_get_difference(env, error));
            }
            UmMessage::OnGetUpdatesState { state } => {
                td.with_updates_env(|um, env| {
                    um.on_get_updates_state(env, state, "GetUpdatesStateQuery")
                });
            }
            UmMessage::OnFailedGetUpdatesState { error } => {
                td.with_updates_env(|um, env| um.on_failed_get_updates_state(env, error));
            }
            UmMessage::OnServerPong { state } => {
                td.with_updates_env(|um, env| um.on_server_pong(env, state));
            }
            UmMessage::TickTimeouts => {
                td.with_updates_env(|um, env| um.tick_timeouts(env));
            }
        }
    }
}

actor_messages! {
    pub enum TdMessage for Td {
        Request { request_id: u64, function: Function, } => request(request_id, function),
        Close => close_impl(false),
        Destroy => close_impl(true),
        /// A completed ConfigManager query — the C++
        /// `ConfigManager::on_result` dispatch. The net step calls this
        /// when a pending query completes; tests drive the config flow
        /// through it.
        ConfigQueryResult { query: ConfigQuery, result: ConfigQueryResult, } => on_config_query_result(query, result),
        /// A completed recoverer simple-config fetch — the C++ fetch
        /// actor's promise delivery (`ConfigRecoverer::on_simple_config`).
        /// Tests drive the recoverer loop through it; the parked fetch's
        /// live executor (the net step) delivers here.
        RecovererSimpleConfigResult { result: Result<SimpleConfigResult, Status>, } => on_recoverer_simple_config_result(result),
        /// A completed recoverer full-config fetch —
        /// `ConfigRecoverer::on_full_config`; the M.3.7.4 executor is the
        /// production sender.
        RecovererFullConfigResult { result: Result<telegram_api::Config, Status>, } => on_recoverer_full_config_result(result),
        /// A driver-thread nudge: the session drivers and the shared
        /// auth data queue their events into `net_shared.events`; this
        /// wakes the actor to drain them (the C++
        /// `send_closure_later(G()->td(), ...)`.
        DrainNetEvents => drain_net_events(),
        /// The end-of-turn deferred-outbox flush — queued behind the
        /// actor messages a net-answer drain emitted (the merger/combiner
        /// re-runs), so their deferred completions answer in the same
        /// wake (the `request` end-of-turn hop for the net plane).
        FlushDeferred => flush_deferred_results(),
    }
}

/// `EditChatAboutQuery::on_success` (ChatManager.cpp:1064-1073) — the
/// per-type description intake over the taken-out managers (the env
/// borrows the remaining `Td` fields, so the managers ride as locals).
fn edit_chat_about_on_success(
    chat_manager: &mut crate::chat_manager::ChatManager,
    user_manager: &mut crate::user_manager::UserManager,
    env: &mut crate::user_manager::UserEnv<'_>,
    dialog_id: crate::messages_manager::DialogId,
    about: String,
) {
    use crate::messages_manager::DialogType;
    match dialog_id.get_type() {
        DialogType::Chat => chat_manager.on_update_chat_description(
            user_manager,
            env,
            dialog_id.get_chat_id(),
            about,
        ),
        DialogType::Channel => chat_manager.on_update_channel_description(
            user_manager,
            env,
            dialog_id.get_channel_id(),
            about,
        ),
        DialogType::User | DialogType::SecretChat | DialogType::None => {
            unreachable!("EditChatAboutQuery on {dialog_id:?}")
        }
    }
}

impl Actor for Td {
    fn start_up(&mut self) {
        self.emit_start_up();
    }

    /// `Td::hangup` (Td.cpp:481-485): the ClientManager's ActorOwn erase
    /// lands here and starts the close machine.
    fn hangup(&mut self) {
        self.close_impl(false);
        self.dec_stop_cnt();
    }

    /// The Td's single actor timeout slot multiplexes the ConfigManager
    /// expire timer, the recoverer wakeup and the UserManager deadlines
    /// (the C++ managers each carry their own timer): the fired timeout
    /// re-requests the expired config, re-runs the recoverer's loop and
    /// ticks the user timeouts; every arm/cancel point then re-arms the
    /// slot at the earliest deadline through `sync_config_timeout`.
    /// The member MultiTimeouts (the user online/emoji-status pair and the
    /// ChatManager channel trio) fire here — their C++ callbacks hop back
    /// into the manager actors; the sweep then re-arms at the next
    /// deadline, like the MultiTimeouts' set/cancel re-arm.
    fn timeout_expired(&mut self) {
        self.tick_alarms();
        let close_flag = self.close_flag != 0;
        // The NotificationManager's two timeout families (M.13): the C++
        // `on_flush_*_timeout_callback`s collapse into `tick_timeouts`.
        {
            let mut env = NotificationEnv {
                global: &mut self.global,
                options: self.option_manager.as_mut(),
                auth_is_authorized: self.auth_manager.is_authorized(),
                auth_is_bot: self.auth_manager.is_bot(),
                updates: &mut self.notification_updates,
            };
            self.notification_manager.tick_timeouts(&mut env);
            self.notification_settings_manager.tick_timeouts(&mut env);
            self.device_token_manager.tick_timeouts(&mut env);
        }
        // The SponsoredMessageManager + PromoDataManager timeout sweeps
        // (M.26): the C++ MultiTimeout callbacks collapse into
        // `tick_timeouts`.
        {
            let (mut sponsored_message_manager, mut sponsored_env) = sponsored_env_split(self);
            sponsored_message_manager.tick_timeouts(&mut sponsored_env);
            self.sponsored_message_manager = sponsored_message_manager;
        }
        {
            let (mut promo_data_manager, mut promo_env) = promo_env_split(self);
            promo_data_manager.tick_timeouts(&mut promo_env);
            self.promo_data_manager = promo_data_manager;
        }

        // The TopDialogManager timeout sweep (M.27).
        {
            let (mut env, top_dialog_manager) = top_dialog_env_split(self);
            top_dialog_manager.tick_timeouts(&mut env);
        }
        // The DialogParticipantManager online-member-count timeout (the
        // M.dp slice): the expired deadlines fire the cache-expiry refresh.
        {
            let now = tdutils::time::now();
            let expired: Vec<i64> = self
                .dialog_participant_manager
                .online_member_count_deadlines
                .iter()
                .filter(|(_, deadline)| **deadline <= now)
                .map(|(&dialog_id, _)| dialog_id)
                .collect();
            for dialog_id in expired {
                self.dialog_participant_manager
                    .online_member_count_deadlines
                    .remove(&dialog_id);
                let (mut env, manager) = dialog_participant_env_split(self);
                manager.on_online_member_count_timeout(
                    &mut env,
                    crate::chat_manager::DialogId::new(dialog_id),
                );
            }
        }
        // The WebPagesManager pending-page timeouts (M.17): the
        // collapsed MultiTimeout fires each due id once.
        {
            let now = tdutils::time::now();
            let due: Vec<i64> = self
                .web_pages_timeouts
                .iter()
                .filter(|(_, deadline)| **deadline <= now)
                .map(|(&key, _)| key)
                .collect();
            for web_page_id in due {
                self.web_pages_timeouts.remove(&web_page_id);
                let (mut env, web_pages_manager) = web_pages_env_split(self);
                web_pages_manager.on_pending_web_page_timeout(&mut env, web_page_id);
            }
        }
        // The InlineQueriesManager timeout sweep (M.21): the C++
        // `on_pending_inline_query_timeout_callback` collapses into
        // `tick_timeouts`.
        {
            let (mut env, inline_queries_manager, _) = inline_env_split(self);
            inline_queries_manager.tick_timeouts(&mut env);
        }
        // The MessageQueryManager timeout families (M.18): the C++
        // `send_message_view_metrics_timeout_callback` and the reload
        // SleepActor collapse into `tick_timeouts`.
        {
            let (mut env, mq_manager) = message_query_env_split(self);
            mq_manager.tick_timeouts(&mut env);
        }
        // The PollManager's three MultiTimeouts (M.19): the C++
        // `on_*_poll_timeout_callback`s collapse into `tick_timeouts`.
        {
            let (mut env, poll_manager) = poll_env_split(self);
            poll_manager.tick_timeouts(&mut env);
        }
        // The messages ladder's channel-difference deadlines (M.10.19):
        // the retry ladder + the final poll timeout fire the shared
        // `on_channel_get_difference_timeout` entry over the alias pair.
        {
            let now = tdutils::time::now();
            let due =
                crate::messages_manager::next_channel_difference_deadline(&self.messages_manager)
                    .is_some_and(|deadline| deadline <= now);
            if due {
                // SAFETY: the alias pair derives from `td_ptr`; the
                // contexts are used strictly one at a time.
                let td_ptr = std::ptr::from_mut(self);
                let manager: &mut crate::messages_manager::MessagesManager =
                    unsafe { &mut (*td_ptr).messages_manager };
                let global: &mut crate::global::Global = unsafe { &mut (*td_ptr).global };
                let msgctx: &mut dyn crate::messages_manager::MessageObjectContext =
                    unsafe { &mut *td_ptr };
                let sendctx: &dyn crate::messages_manager::SendMessageContext = unsafe { &*td_ptr };
                let state: &mut dyn crate::messages_manager::ReadStateContext =
                    unsafe { crate::td::split_context_alias(td_ptr) };
                let cdctx: &mut dyn crate::messages_manager::ChannelDifferenceContext =
                    unsafe { &mut *td_ptr };
                crate::messages_manager::tick_channel_difference_timeouts(
                    global, manager, msgctx, sendctx, state, cdctx, now,
                );
            }
        }
        let actions = self
            .config_manager
            .as_mut()
            .map(|config_manager| config_manager.on_timeout(close_flag))
            .unwrap_or_default();
        self.apply_config_actions(actions);

        // The StateManager's debounced flush (the C++ actor's own
        // `set_timeout_at`): the armed deadline fires the pending state.
        if let Some(state) = self.state_manager.loop_(tdutils::time::now()) {
            self.send_real_connection_state(state);
        }
        self.sync_config_timeout();

        let environment = self.recoverer_env();
        let actions = self
            .config_recoverer
            .as_mut()
            .map(|recoverer| recoverer.loop_(&environment))
            .unwrap_or_default();
        self.apply_recoverer_actions(actions);

        // Pre-init there is no OptionManager to build the UserEnv from —
        // the manager ticks skip, but the tail flushes must still run: a
        // pre-init alarm (setAlarm is preinitialization) settles its parked
        // promise through this exact path.
        if let Some(options) = self.option_manager.as_mut() {
            let mut env = UserEnv {
                global: &mut self.global,
                options,
                auth_is_bot: self.auth_manager.is_bot(),
            };
            self.user_manager.tick_timeouts(&mut env);
            self.chat_manager
                .tick_timeouts(&mut self.user_manager, &mut env);
        }
        // The StorageManager's auto-gc timeout (T.8): the C++ actor's own
        // timer, collapsed into the shared slot's fire — before the flush
        // so the gc's unlink updates ride the same drive.
        self.tick_storage_gc();
        self.flush_user_updates();
        self.rearm_user_timeouts();

        // The update engine's timers (the gap fills, the throttled pmc
        // saves, the getDifference retry and the data reloaders; M.7.18).
        // The C++ timers are the manager's own AlarmTimeouts whose fires
        // hop into the manager's slice — the fixpoint rides the bridge.
        // Pre-init the ticks skip (no bridge yet) — the tail flush below
        // must still run: a pre-init alarm settles its parked promise
        // through it.
        if !self.updates_manager_bridge.empty() {
            self.um_send_later(UmMessage::TickTimeouts);
        } else {
            let net = self.updates_net();
            if let Some(options) = self.option_manager.as_mut() {
                let mut env = TdUpdatesEnv {
                    global: &mut self.global,
                    options,
                    auth_is_authorized: self.auth_manager.is_authorized(),
                    auth_is_bot: self.auth_manager.is_bot(),
                    my_id: self.user_manager.get_my_id().get(),
                    can_ignore_background_updates: self.can_ignore_background_updates,
                    net,
                };
                self.updates_manager.tick_timeouts(&mut env);
            }
        }
        // The driver events (salts persists, key changes, updates) pump
        // through the same slot when no DrainNetEvents nudge beat it.
        self.drain_net_events();
        // The callback-parked auth + walking-skeleton answers.
        self.dispatch_completed_walking();
        self.flush_deferred_results();
    }

    fn tear_down(&mut self) {
        // The C++ reset_actor sequence (Td.cpp:757): the manager actors
        // are destroyed before the Td state they reach into — a queued
        // hangup would run a bridge slice past the owner's death, so the
        // registration goes down synchronously here.
        if !self.updates_manager_bridge.empty() {
            Scheduler::instance().destroy_actor_sync(&self.updates_manager_bridge.get());
        }
        self.updates_manager_bridge = ActorOwn::default();
        self.close();
    }

    // No `loop_`: the pending-query poll arrives with the net step (the
    // C++ `Td::loop` yields to drive the NetQueryDispatcher).
}

/// Field-split the `Td` for the PollManager calls: the env borrows the
/// manager surfaces, the split returns the poll manager itself.
pub(crate) fn poll_env_split(
    td: &mut Td,
) -> (
    crate::poll_manager::PollManagerEnvImpl<'_>,
    &mut crate::poll_manager::PollManager,
) {
    let crate::td::Td {
        global,
        option_manager,
        auth_manager,
        user_manager,
        chat_manager,
        file_manager,
        poll_manager,
        poll_updates,
        ..
    } = td;
    (
        crate::poll_manager::PollManagerEnvImpl {
            global,
            options: option_manager.as_mut(),
            auth_is_bot: auth_manager.is_bot(),
            user_manager,
            chat_manager,
            file_manager: std::sync::Arc::clone(file_manager),
            updates: poll_updates,
        },
        poll_manager,
    )
}

/// The `G()`/manager slice the collapsed NotificationManager reads through
/// (the C++ manager reads the same surfaces off its `Td *td_` directly).
/// The `send_update`s buffer into [`Td::notification_updates`] and Td
/// drains them — the collapsed `send_closure(G()->td(), &Td::send_update)`
/// hop.
pub(crate) struct NotificationEnv<'a> {
    pub(crate) global: &'a mut Global,
    /// `None` once the option manager is torn down; the getters answer
    /// their defaults, matching the C++ close ordering closely enough for
    /// the destroy path.
    pub(crate) options: Option<&'a mut OptionManager>,
    pub(crate) auth_is_authorized: bool,
    pub(crate) auth_is_bot: bool,
    pub(crate) updates: &'a mut Vec<td_api::Update>,
}

/// The [`crate::people_nearby_manager::PeopleNearbyManagerEnv`] over the
/// `Td` fields — the collapsed constructor surface (built per call, never
/// held across calls).
pub(crate) struct PeopleNearbyEnv<'a> {
    pub(crate) is_bot: bool,
    pub(crate) global: &'a mut Global,
}

