/// The statistics-plane env over the `Td` fields.
pub(crate) struct StatisticsEnv<'a> {
    pub(crate) global: &'a mut Global,
    pub(crate) updates: &'a mut Vec<td_api::Update>,
}

impl StatisticsManagerEnv for StatisticsEnv<'_> {
    fn close_flag(&self) -> bool {
        self.global.close_flag()
    }

    fn send_update(&mut self, update: td_api::Update) {
        self.updates.push(update);
    }
}

/// The recorded-dc slot type — catches a synchronously-resolved
/// [`crate::chat_manager::DcId`] answer (the refire leaves it empty and
/// parks the continuation instead).
type DcIdSlot =
    std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<crate::chat_manager::DcId>>>>;

/// The recorded dc promise paired with its [`DcIdSlot`].
fn recorded_dc_id_promise() -> (Promise<crate::chat_manager::DcId>, DcIdSlot) {
    struct Rec(DcIdSlot);
    impl tdutils::promise::PromiseInterface<crate::chat_manager::DcId> for Rec {
        fn set_value(&mut self, value: crate::chat_manager::DcId) {
            *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
        }

        fn set_error(&mut self, error: Status) {
            *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
        }
    }
    let slot: DcIdSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
    (
        Promise::from_interface(Rec(std::sync::Arc::clone(&slot))),
        slot,
    )
}

impl Td {
    /// `StatisticsManager::get_channel_statistics` (StatisticsManager.cpp:746-758)
    /// — the collapsed manager flow at the Td level: the dc_id chain
    /// over the real [`ChatManager::get_channel_statistics_dc_id`]. A
    /// synchronously-resolved dc parks the request at the stats query
    /// seam; a missing/unexact dc refires the full query with the
    /// continuation parked ([`Td::finish_pending_channel_statistics_dc_id`]
    /// drains it); the error tail fails the request.
    pub(crate) fn get_channel_statistics_dc_chain(
        &mut self,
        dialog_id: crate::chat_manager::DialogId,
        is_dark: bool,
        mut promise: Promise<td_api::ChatStatistics>,
    ) {
        let (dc_promise, slot) = recorded_dc_id_promise();
        self.with_chat_intake(|chat_manager, user_manager, env| {
            chat_manager.get_channel_statistics_dc_id(
                user_manager,
                env,
                dialog_id,
                true,
                dc_promise,
            );
        });
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(dc_id)) => {
                // send_get_channel_stats_query (cpp:753-764) — the query
                // seam parks the promise (net-drain 38); the seam log
                // rides the env
                let _ = dc_id;
                let mut env = StatisticsEnv {
                    global: &mut self.global,
                    updates: &mut self.statistics_updates,
                };
                env.send_get_channel_stats_query(
                    crate::dialog_id::DialogId::new(dialog_id.get()),
                    is_dark,
                );
                self.statistics_dc_parked
                    .push((dialog_id, is_dark, promise));
            }
            Some(tdutils::status::Result::Err(status)) => promise.set_error(status),
            None => {
                // the refire — the full query is out with the
                // continuation parked; the answer leg settles the chain
                self.statistics_dc_parked
                    .push((dialog_id, is_dark, promise));
            }
        }
    }
}

/// The premium-plane env over the whole `Td` — the request arms take the
/// manager out of `Td` and hand the remainder to the env (the
/// `privacy_env_split` convention), so the send legs resolve peers,
/// chats and users through the real managers.
pub(crate) struct PremiumTdEnv<'a> {
    pub(crate) td: &'a mut Td,
}

/// The disjoint manager/env take-out for the premium manager — the
/// manager out, the env over the `Td` remainder (the `privacy_env_split`
/// convention).
pub(crate) fn premium_env_split(td: &mut Td) -> (crate::premium::PremiumManager, PremiumTdEnv<'_>) {
    let manager = std::mem::take(&mut td.premium_manager);
    (manager, PremiumTdEnv { td })
}

impl PremiumEnv for PremiumTdEnv<'_> {
    fn get_option_integer(&self, name: &str) -> i64 {
        self.td
            .option_manager
            .as_ref()
            .map_or(0, |options| options.get_option_integer(name, 0))
    }

    fn get_option_string(&self, name: &str, default_value: &str) -> String {
        self.td.option_manager.as_ref().map_or_else(
            || default_value.to_string(),
            |options| options.get_option_string(name, default_value),
        )
    }

    fn send_update(&mut self, update: td_api::Update) {
        self.td.send_update(td_api::Object::from(update));
    }

    // The whole-Td reads (DialogManager/ChatManager/UserManager) — the
    // `PrivacyEnv`/`TdSponsoredEnv` arms over the same managers.
    fn have_dialog_force(&mut self, dialog_id: crate::dialog_id::DialogId, source: &str) -> bool {
        crate::dialog_manager::have_dialog_force(self.td, dialog_id, source)
    }

    fn get_channel_status(
        &mut self,
        channel_id: crate::chat_manager::ChannelId,
    ) -> crate::chat_manager::DialogParticipantStatus {
        self.td.chat_manager.get_channel_status(channel_id)
    }

    fn get_input_peer(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
        access_rights: crate::user_manager::AccessRights,
    ) -> Option<telegram_api::InputPeer> {
        crate::dialog_manager::get_input_peer(self.td, dialog_id, access_rights)
    }

    fn on_get_dialog_error(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
        status: &tdutils::status::Status,
        source: &str,
    ) {
        crate::dialog_manager::on_get_dialog_error(&self.td.global, dialog_id, status, source);
    }

    fn on_get_users(&mut self, users: Vec<telegram_api::User>, source: &str) {
        let options = self.td.option_manager.as_mut();
        if let Some(options) = options {
            let mut env = UserEnv {
                global: &mut self.td.global,
                options,
                auth_is_bot: self.td.auth_manager.is_bot(),
            };
            self.td.user_manager.on_get_users(&mut env, users, source);
        }
    }

    fn on_get_chats(&mut self, chats: Vec<telegram_api::Chat>, source: &str) {
        let options = self.td.option_manager.as_mut();
        if let Some(options) = options {
            let mut env = UserEnv {
                global: &mut self.td.global,
                options,
                auth_is_bot: self.td.auth_manager.is_bot(),
            };
            self.td
                .chat_manager
                .on_get_chats(&mut self.td.user_manager, &mut env, chats, source);
        }
    }

    fn have_channel_force(
        &mut self,
        channel_id: crate::chat_manager::ChannelId,
        source: &str,
    ) -> bool {
        let options = self.td.option_manager.as_mut();
        let Some(options) = options else {
            return false;
        };
        let mut env = UserEnv {
            global: &mut self.td.global,
            options,
            auth_is_bot: self.td.auth_manager.is_bot(),
        };
        self.td.chat_manager.have_channel_force(
            &mut self.td.user_manager,
            &mut env,
            channel_id,
            source,
        )
    }

    fn force_create_dialog(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
        source: &str,
        _force_read: bool,
    ) {
        crate::dialog_manager::force_create_dialog(self.td, dialog_id, source)
    }

    fn get_input_user(
        &mut self,
        user_id: crate::user_manager::UserId,
    ) -> tdutils::status::Result<telegram_api::InputUser> {
        let env = UserEnv {
            global: &mut self.td.global,
            options: self
                .td
                .option_manager
                .as_mut()
                .expect("premium calls run with the initialized option manager"),
            auth_is_bot: self.td.auth_manager.is_bot(),
        };
        match self.td.user_manager.get_input_user(&env, user_id) {
            Ok(input_user) => tdutils::status::Result::Ok(input_user),
            Err(status) => tdutils::status::Result::Err(status),
        }
    }

    fn have_dialog_info_force(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
        source: &str,
    ) -> bool {
        crate::dialog_manager::have_dialog_info_force(self.td, dialog_id, source)
    }

    fn get_message_sender_object(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
        source: &str,
    ) -> td_api::MessageSender {
        crate::dialog_manager::get_message_sender_object(self.td, dialog_id, source)
    }

    fn get_user_id_object(&mut self, user_id: crate::user_manager::UserId, source: &str) -> i64 {
        let mut env = UserEnv {
            global: &mut self.td.global,
            options: self
                .td
                .option_manager
                .as_mut()
                .expect("premium calls run with the initialized option manager"),
            auth_is_bot: self.td.auth_manager.is_bot(),
        };
        self.td
            .user_manager
            .get_user_id_object(&mut env, user_id, source)
    }

    // `MessagesManager::get_giveaway_message_id` (MessagesManager.cpp
    // :36676-36697) — the M.10.19 force-lookup band over the alias pair
    // (the memory probe + the message-db load seam + the content/id
    // bands).
    fn get_giveaway_message_id(
        &mut self,
        dialog_id: crate::messages_manager::DialogId,
        message_id: crate::messages_manager::MessageId,
    ) -> tdutils::status::Result<crate::messages_manager::ServerMessageId> {
        // SAFETY: the alias pair derives from `td_ptr`; the band uses
        // the contexts strictly one at a time.
        let td_ptr = std::ptr::from_mut(self.td);
        let manager: &mut crate::messages_manager::MessagesManager =
            unsafe { &mut (*td_ptr).messages_manager };
        let global: &mut crate::global::Global = unsafe { &mut (*td_ptr).global };
        let sendctx: &dyn crate::messages_manager::SendMessageContext = unsafe { &*td_ptr };
        let state: &mut dyn crate::messages_manager::ReadStateContext =
            unsafe { crate::td::split_context_alias(td_ptr) };
        let reactions_ctx: &dyn crate::messages_manager::DialogReactionsContext =
            unsafe { &*td_ptr };
        match crate::messages_manager::get_giveaway_message_id(
            global,
            manager,
            sendctx,
            state,
            reactions_ctx,
            dialog_id,
            message_id,
        ) {
            std::result::Result::Ok(server_message_id) => {
                tdutils::status::Result::Ok(server_message_id)
            }
            std::result::Result::Err(status) => tdutils::status::Result::Err(status),
        }
    }

    // `GetPremiumPromoQuery::send` (Premium.cpp:321-323).
    fn send_get_premium_promo_query(&mut self) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::GetPremiumPromo,
                telegram_api::Function::help_getPremiumPromo(telegram_api::help_getPremiumPromo),
            ),
            None => {
                tdutils::log_info!("Send help.getPremiumPromo — [net-inert]");
            }
        }
    }

    // The two landed sends (Premium.cpp:50-53/583-585) — the answers
    // drain through `Td::on_premium_net_answer`.
    fn send_get_premium_gift_options_query(&mut self) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::GetPremiumGiftCodeOptions,
                telegram_api::Function::payments_getPremiumGiftCodeOptions(
                    telegram_api::payments_getPremiumGiftCodeOptions {
                        flags: 0,
                        boost_peer: None,
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send payments.getPremiumGiftCodeOptions — [net-inert]");
            }
        }
    }

    fn send_apply_gift_code_query(&mut self, code: &str) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::ApplyGiftCode,
                telegram_api::Function::payments_applyGiftCode(
                    telegram_api::payments_applyGiftCode {
                        slug: code.to_string(),
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send payments.applyGiftCode for {code} — [net-inert]");
            }
        }
    }

    // `GetPremiumGiveawayOptionsQuery::send` (Premium.cpp:471-481) — the
    // BOOST_PEER flag (flags.0) with the resolved boost peer; the kind
    // carries the boosted dialog for the `on_error` tail.
    fn send_get_premium_giveaway_options_query(
        &mut self,
        boost_peer: telegram_api::InputPeer,
        boosted_dialog_id: i64,
    ) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::GetPremiumGiveawayOptions { boosted_dialog_id },
                telegram_api::Function::payments_getPremiumGiftCodeOptions(
                    telegram_api::payments_getPremiumGiftCodeOptions {
                        flags: 1, // BOOST_PEER_MASK
                        boost_peer: Some(Box::new(boost_peer)),
                    },
                ),
            ),
            None => tdutils::log_info!(
                "Send payments.getPremiumGiftCodeOptions for {boosted_dialog_id} — [net-inert]"
            ),
        }
    }

    // `GetGiveawayInfoQuery::send` (Premium.cpp:741-748) — the Read peer
    // resolves at the manager's send leg; the kind carries the dialog for
    // the `on_error` tail.
    fn send_get_giveaway_info_query(
        &mut self,
        dialog_id: i64,
        peer: telegram_api::InputPeer,
        msg_id: i32,
    ) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::GetGiveawayInfo { dialog_id },
                telegram_api::Function::payments_getGiveawayInfo(
                    telegram_api::payments_getGiveawayInfo {
                        peer: Some(Box::new(peer)),
                        msg_id,
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send payments.getGiveawayInfo({dialog_id}) — [net-inert]");
            }
        }
    }

    // `CheckGiftCodeQuery::send` (Premium.cpp:517-519) — the slug rides
    // the query; the users/chats intakes run at the answer.
    fn send_check_gift_code_query(&mut self, code: &str) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::CheckGiftCode,
                telegram_api::Function::payments_checkGiftCode(
                    telegram_api::payments_checkGiftCode {
                        slug: code.to_string(),
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send payments.checkGiftCode for {code} — [net-inert]");
            }
        }
    }

    // `CanPurchasePremiumQuery::send` (Premium.cpp:830-838) — the store
    // purpose rides the query.
    fn send_can_purchase_premium_query(&mut self, purpose: telegram_api::InputStorePaymentPurpose) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::CanPurchasePremium,
                telegram_api::Function::payments_canPurchaseStore(
                    telegram_api::payments_canPurchaseStore {
                        purpose: Some(purpose),
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send payments.canPurchaseStore — [net-inert]");
            }
        }
    }

    // The assign pair (Premium.cpp:860-893) — the AppStore receipt rides
    // the wire as bytes, the PlayMarket one as the built dataJSON.
    fn send_assign_store_transaction_query(
        &mut self,
        receipt: Vec<u8>,
        purpose: telegram_api::InputStorePaymentPurpose,
        is_app_store: bool,
    ) {
        let function = if is_app_store {
            telegram_api::Function::payments_assignAppStoreTransaction(
                telegram_api::payments_assignAppStoreTransaction {
                    receipt,
                    purpose: Some(purpose),
                },
            )
        } else {
            telegram_api::Function::payments_assignPlayMarketTransaction(
                telegram_api::payments_assignPlayMarketTransaction {
                    receipt: Some(telegram_api::DataJSON {
                        // the manager-built JSON receipt (valid UTF-8 by
                        // construction; the default keeps the seam total)
                        data: String::from_utf8(receipt).unwrap_or_default(),
                    }),
                    purpose: Some(purpose),
                },
            )
        };
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::AssignStoreTransaction { is_app_store },
                function,
            ),
            None => {
                tdutils::log_info!("Send the store-transaction assign — [net-inert]");
            }
        }
    }

    // `LaunchPrepaidGiveawayQuery::send` (Premium.cpp:710-718) — the
    // Write peer of the boosted channel + the purpose build (the
    // premium/stars giveaway forms over the payments surface; the C++
    // amount placeholder 12345).
    fn send_launch_prepaid_giveaway_query(
        &mut self,
        giveaway_id: i64,
        parameters: &crate::payments::GiveawayParameters,
        user_count: i32,
        star_count: i64,
    ) {
        let Some(net) = self.td.premium_net() else {
            return tdutils::log_info!(
                "Send payments.launchPrepaidGiveaway({giveaway_id}) — [net-inert]"
            );
        };
        let dialog_id = parameters.get_boosted_dialog_id();
        let input_peer = crate::dialog_manager::get_input_peer(
            self.td,
            dialog_id,
            crate::user_manager::AccessRights::Write,
        );
        // the C++ CHECK(input_peer != nullptr)
        let input_peer = match input_peer {
            Some(peer) => peer,
            None => panic!("launchPrepaidGiveaway has no input peer"),
        };
        let mut payments_env = crate::td::PaymentsTdEnv { td: self.td };
        let purpose = if star_count == 0 {
            parameters.get_input_store_payment_premium_giveaway(&mut payments_env, "", 0)
        } else {
            parameters.get_input_store_payment_stars_giveaway(
                &mut payments_env,
                "",
                12345,
                user_count,
                star_count,
            )
        };
        net.dispatch(
            PremiumNetKind::LaunchPrepaidGiveaway,
            telegram_api::Function::payments_launchPrepaidGiveaway(
                telegram_api::payments_launchPrepaidGiveaway {
                    peer: Some(Box::new(input_peer)),
                    giveaway_id,
                    purpose: Some(purpose),
                },
            ),
        );
    }

    // `GetPremiumGiftPaymentFormQuery::send` (Premium.cpp:658-663) — the
    // flag-less form query (theme_params absent); the answer routes
    // through the manager intake and chains `SendPremiumGiftQuery`.
    fn send_get_premium_gift_payment_form_query(
        &mut self,
        input_invoice: telegram_api::InputInvoice,
    ) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::GetPremiumGiftPaymentForm,
                telegram_api::Function::payments_getPaymentForm(
                    telegram_api::payments_getPaymentForm {
                        flags: 0,
                        invoice: Some(input_invoice),
                        theme_params: None,
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send payments.getPaymentForm — [net-inert]");
            }
        }
    }

    // `SendPremiumGiftQuery::send` (Premium.cpp:612-614) — the form id +
    // the send invoice; the `payments.paymentResult` answer re-enters
    // `on_get_updates` with the promise.
    fn send_send_premium_gift_query(
        &mut self,
        send_input_invoice: telegram_api::InputInvoice,
        payment_form_id: i64,
    ) {
        match self.td.premium_net() {
            Some(net) => net.dispatch(
                PremiumNetKind::SendPremiumGift,
                telegram_api::Function::payments_sendStarsForm(
                    telegram_api::payments_sendStarsForm {
                        form_id: payment_form_id,
                        invoice: Some(send_input_invoice),
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send payments.sendStarsForm — [net-inert]");
            }
        }
    }

    // `get_premium_gift_text` (Premium.cpp:209-222) over the payments
    // surface — the field-split payments env (the conversion-seam
    // convention); the seam's own posture answers the empty-text case.
    fn premium_gift_text(
        &mut self,
        text: Option<td_api::FormattedText>,
    ) -> tdutils::status::Result<Option<telegram_api::TextWithEntities>> {
        let mut payments_env = crate::td::PaymentsTdEnv { td: self.td };
        <crate::td::PaymentsTdEnv<'_> as crate::payments::PaymentsEnv>::premium_gift_text(
            &mut payments_env,
            text,
        )
    }

    // `get_message_text(td_->user_manager_.get(), status_text,
    // status_entities, true, true, 0, false, …)` +
    // `get_formatted_text_object(td_->user_manager_.get(), state,
    // true, -1)` (Premium.cpp:335-337/382-383) over the formatted-text
    // surface (the PremiumTdEnv UserManagerLike).
    fn premium_promo_status_text(
        &mut self,
        status_text: String,
        status_entities: Vec<telegram_api::MessageEntity>,
    ) -> td_api::FormattedText {
        let state = crate::message_entity::get_message_text(
            Some(self),
            status_text,
            status_entities,
            true,
            true,
            0,
            false,
            "GetPremiumPromoQuery",
        );
        crate::message_entity::get_formatted_text_object(Some(self), &state, true, -1)
    }

    // `td_->documents_manager_->on_get_document(document, DialogId(),
    // false, false, nullptr, Document::Type::Animation)`
    // (Premium.cpp:360-362) — the real documents intake over the
    // `documents_env` split.
    fn on_get_document(&mut self, document: telegram_api::document) -> crate::document::Document {
        let (mut env, documents) = self.td.documents_env();
        documents.on_get_document(
            &mut env,
            crate::documents_manager::RemoteDocument::from_server_document(document),
            DialogId::new(0),
            false,
            false,
            crate::document::DocumentType::Animation,
            crate::documents_manager::Subtype::Other,
        )
    }

    // `dismiss_suggested_action(SuggestedAction{type}, Promise<Unit>())`
    // (Premium.cpp:1461-1465) over the suggested-action manager — the
    // `AccountEnv` build (the `hide_archive_and_mute_suggested_action`
    // precedent); the `DismissSuggestionQuery` seam parks with the
    // suggested-action net slice.
    fn dismiss_suggested_action(
        &mut self,
        action_type: crate::suggested_action::SuggestedActionType,
    ) {
        let this = &mut *self.td;
        let crate::td::Td {
            global,
            option_manager,
            user_manager,
            device_token_manager,
            auth_manager,
            suggested_action_manager,
            account_updates,
            ..
        } = this;
        let mut action = crate::suggested_action::SuggestedAction::default();
        action.init(action_type);
        let mut account_env = AccountEnv {
            global,
            options: option_manager.as_mut(),
            user_manager,
            device_token_manager,
            auth_is_bot: auth_manager.is_bot(),
            updates: account_updates,
            net: None,
        };
        // the C++ internal callers drop their promises
        suggested_action_manager.dismiss_suggested_action(
            &mut account_env,
            action,
            Promise::default(),
        );
    }

    // `get_input_store_payment_purpose` (Premium.cpp:220-300) — the
    // conversion runs over the payments surface; the field-split
    // payments env over the same Td (the `payments_arm` convention).
    fn get_input_store_payment_purpose(
        &mut self,
        purpose: Option<td_api::StorePaymentPurpose>,
    ) -> tdutils::status::Result<telegram_api::InputStorePaymentPurpose> {
        let mut payments_env = crate::td::PaymentsTdEnv { td: self.td };
        crate::premium::get_input_store_payment_purpose(&mut payments_env, purpose)
    }

    // `GiveawayParameters::get_giveaway_parameters`
    // (GiveawayParameters.cpp:39-80) over the payments surface.
    fn get_giveaway_parameters(
        &mut self,
        parameters: Option<&td_api::GiveawayParameters>,
    ) -> tdutils::status::Result<crate::payments::GiveawayParameters> {
        let mut payments_env = crate::td::PaymentsTdEnv { td: self.td };
        crate::payments::GiveawayParameters::get_giveaway_parameters(&mut payments_env, parameters)
    }
}

/// The `get_message_text`/`get_formatted_text_object` resolver half of
/// [`PremiumTdEnv`] (the `SupportEnvTd` shape over the user manager).
impl crate::message_entity::UserManagerLike for PremiumTdEnv<'_> {
    fn resolve_user_id_object(
        &mut self,
        user_id: crate::user_manager::UserId,
        source: &str,
    ) -> i64 {
        let mut env = UserEnv {
            global: &mut self.td.global,
            options: self
                .td
                .option_manager
                .as_mut()
                .expect("premium answers run with the initialized option manager"),
            auth_is_bot: self.td.auth_manager.is_bot(),
        };
        self.td
            .user_manager
            .get_user_id_object(&mut env, user_id, source)
    }

    fn ensure_input_user(&mut self, user_id: crate::user_manager::UserId) -> Result<(), Status> {
        let env = UserEnv {
            global: &mut self.td.global,
            options: self
                .td
                .option_manager
                .as_mut()
                .expect("premium answers run with the initialized option manager"),
            auth_is_bot: self.td.auth_manager.is_bot(),
        };
        self.td
            .user_manager
            .get_input_user(&env, user_id)
            .map(|_| ())
    }

    fn have_min_user(&self, user_id: crate::user_manager::UserId) -> bool {
        self.td.user_manager.have_min_user(user_id)
    }

    fn get_input_user_force(
        &mut self,
        user_id: crate::user_manager::UserId,
    ) -> telegram_api::InputUser {
        let env = UserEnv {
            global: &mut self.td.global,
            options: self
                .td
                .option_manager
                .as_mut()
                .expect("premium answers run with the initialized option manager"),
            auth_is_bot: self.td.auth_manager.is_bot(),
        };
        self.td.user_manager.get_input_user_force(&env, user_id)
    }
}

/// The quick-reply env over the whole `Td` — the send arms hand the
/// `Td` remainder to the env (the `PrivacyEnv` convention).
pub(crate) struct QuickReplyEnv<'a> {
    pub(crate) td: &'a mut Td,
}

/// The [`QuickReplyEnv`] split — the manager out, the env over the
/// `Td` remainder (the `privacy_env_split` convention).
pub(crate) fn quick_reply_env_split(
    td: &mut Td,
) -> (
    crate::quick_reply_manager::QuickReplyManager,
    QuickReplyEnv<'_>,
) {
    let manager = std::mem::take(&mut td.quick_reply_manager);
    (manager, QuickReplyEnv { td })
}

impl QuickReplyManagerEnv for QuickReplyEnv<'_> {
    fn close_flag(&self) -> bool {
        self.td.global.close_flag()
    }

    fn send_update(&mut self, _update: td_api::Update) {}

    // The four sends (QuickReplyManager.cpp:99/125/153/220) — the
    // `Promise<Unit>` handlers park at the manager lot.
    fn send_edit_quick_reply_shortcut_query(&mut self, shortcut_id: i32, name: &str) {
        match self.td.quick_reply_net() {
            Some(net) => net.dispatch(
                QuickReplyNetKind::EditShortcut,
                telegram_api::Function::messages_editQuickReplyShortcut(
                    telegram_api::messages_editQuickReplyShortcut {
                        shortcut_id,
                        shortcut: name.to_string(),
                    },
                ),
            ),
            None => tdutils::log_info!(
                "Send messages.editQuickReplyShortcut({shortcut_id}, {name}) — [net-inert]"
            ),
        }
    }

    fn send_delete_quick_reply_shortcut_query(&mut self, shortcut_id: i32) {
        match self.td.quick_reply_net() {
            Some(net) => net.dispatch(
                QuickReplyNetKind::DeleteShortcut,
                telegram_api::Function::messages_deleteQuickReplyShortcut(
                    telegram_api::messages_deleteQuickReplyShortcut { shortcut_id },
                ),
            ),
            None => tdutils::log_info!(
                "Send messages.deleteQuickReplyShortcut({shortcut_id}) — [net-inert]"
            ),
        }
    }

    fn send_reorder_quick_replies_query(&mut self, shortcut_ids: &[i32]) {
        match self.td.quick_reply_net() {
            Some(net) => net.dispatch(
                QuickReplyNetKind::Reorder,
                telegram_api::Function::messages_reorderQuickReplies(
                    telegram_api::messages_reorderQuickReplies {
                        order: shortcut_ids.to_vec(),
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send messages.reorderQuickReplies — [net-inert]");
            }
        }
    }

    fn send_delete_quick_reply_messages_query(&mut self, shortcut_id: i32, message_ids: &[i64]) {
        match self.td.quick_reply_net() {
            Some(net) => net.dispatch(
                QuickReplyNetKind::DeleteMessages { shortcut_id },
                telegram_api::Function::messages_deleteQuickReplyMessages(
                    telegram_api::messages_deleteQuickReplyMessages {
                        shortcut_id,
                        id: message_ids.iter().map(|&id| id as i32).collect(),
                    },
                ),
            ),
            None => tdutils::log_info!(
                "Send messages.deleteQuickReplyMessages({shortcut_id}) — [net-inert]"
            ),
        }
    }
}

/// The boost-plane env over the `Td` fields.
pub(crate) struct BoostEnv<'a> {
    pub(crate) global: &'a mut Global,
    pub(crate) options: Option<&'a mut OptionManager>,
    pub(crate) chat_manager: &'a mut crate::chat_manager::ChatManager,
}

impl BoostManagerEnv for BoostEnv<'_> {
    fn close_flag(&self) -> bool {
        self.global.close_flag()
    }

    fn get_option_integer(&self, name: &str, default_value: i64) -> i64 {
        self.options.as_ref().map_or(default_value, |options| {
            options.get_option_integer(name, default_value)
        })
    }

    fn send_update(&mut self, _update: td_api::Update) {}

    fn check_dialog_access(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
    ) -> std::result::Result<(), tdutils::status::Status> {
        if dialog_id.is_valid() {
            Ok(())
        } else {
            Err(tdutils::status::Status::error(400, "Chat not found"))
        }
    }

    fn get_channel_first_username(&mut self, channel_id: crate::chat_manager::ChannelId) -> String {
        // `ChatManager::get_channel_first_username` — the M.5 surface; the
        // seam answers the empty username.
        let _ = (
            self.chat_manager as &mut crate::chat_manager::ChatManager,
            channel_id,
        );
        String::new()
    }
}

/// The [`crate::autosave_manager::AutosaveManagerEnv`] over the `Td`
/// fields — built per call with the field-split borrows (the
/// `NotificationEnv` convention), never held across calls. The sqlite pmc
/// surface routes to `TdDb::common_kv` (the C++ `get_sqlite_pmc` home);
/// the calls are gated on `use_message_database` by the manager, matching
/// the C++ branch that guards them.
pub(crate) struct AutosaveEnv<'a> {
    pub(crate) global: &'a mut Global,
    pub(crate) updates: &'a mut Vec<td_api::Update>,
}

impl crate::autosave_manager::AutosaveManagerEnv for AutosaveEnv<'_> {
    fn close_flag(&self) -> bool {
        self.global.close_flag()
    }

    fn use_message_database(&self) -> bool {
        self.global.use_message_database()
    }

    fn sqlite_pmc_get_raw(&mut self, key: &[u8]) -> Vec<u8> {
        self.global.td_db().common_kv().get(key)
    }

    fn sqlite_pmc_set_raw(&mut self, key: &[u8], value: &[u8]) {
        self.global.td_db().common_kv().set(key, value);
    }

    fn binlog_pmc_erase(&mut self, key: &str) {
        self.global.binlog_pmc().erase(key);
    }

    fn send_update(&mut self, update: td_api::Update) {
        self.updates.push(update);
    }

    /// the simplified dialog seam until the M.5/M.7 dialog integration
    /// (the BoostEnv convention)
    fn check_dialog_access(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
    ) -> Result<(), tdutils::status::Status> {
        if dialog_id.is_valid() {
            Ok(())
        } else {
            Err(tdutils::status::Status::error(400, "Chat not found"))
        }
    }

    fn force_create_dialog(&mut self, _dialog_id: crate::dialog_id::DialogId) {
        // `dialog_manager::force_create_dialog` — the M.6/M.7 cache seam;
        // every dialog id is resolvable in the collapsed cache
    }
}

/// The [`crate::attach_menu_manager::AttachMenuManagerEnv`] over the `Td`
/// fields — built per call with the field-split borrows (the
/// `NotificationEnv` convention), never held across calls; the file
/// manager rides its `Arc` clone so the disjoint borrows hold.
pub(crate) struct AttachMenuEnv<'a> {
    pub(crate) global: &'a mut Global,
    pub(crate) options: Option<&'a mut OptionManager>,
    pub(crate) auth_is_authorized: bool,
    pub(crate) auth_is_bot: bool,
    pub(crate) user_manager: &'a mut UserManager,
    pub(crate) file_manager: std::sync::Arc<parking_lot::Mutex<crate::files::FileManager>>,
    pub(crate) file_reference_manager: &'a mut crate::files::FileReferenceManager,
    pub(crate) updates: &'a mut Vec<td_api::Update>,
}

impl crate::attach_menu_manager::AttachMenuManagerEnv for AttachMenuEnv<'_> {
    fn close_flag(&self) -> bool {
        self.global.close_flag()
    }

    fn is_authorized(&self) -> bool {
        self.auth_is_authorized
    }

    fn is_bot(&self) -> bool {
        self.auth_is_bot
    }

    fn use_chat_info_database(&self) -> bool {
        self.global.use_chat_info_database()
    }

    fn binlog_pmc_get_raw(&mut self, key: &[u8]) -> Vec<u8> {
        self.global.binlog_pmc().get_raw(key)
    }

    fn binlog_pmc_set_raw(&mut self, key: &[u8], value: &[u8]) {
        self.global.binlog_pmc().set_raw(key, value);
    }

    fn binlog_pmc_erase(&mut self, key: &str) {
        self.global.binlog_pmc().erase(key);
    }

    fn send_update(&mut self, update: td_api::Update) {
        self.updates.push(update);
    }

    fn get_input_user(
        &mut self,
        user_id: UserId,
    ) -> Result<telegram_api::InputUser, tdutils::status::Status> {
        let user_env = UserEnv {
            global: self.global,
            options: self
                .options
                .as_mut()
                .expect("attach-menu requests run with the initialized option manager"),
            auth_is_bot: self.auth_is_bot,
        };
        self.user_manager.get_input_user(&user_env, user_id)
    }

    fn get_bot_data(
        &mut self,
        user_id: UserId,
    ) -> Result<crate::user_manager::BotData, tdutils::status::Status> {
        self.user_manager.get_bot_data(user_id)
    }

    fn have_accessible_user(&self, user_id: UserId) -> bool {
        self.user_manager.have_accessible_user(user_id)
    }

    fn get_user_id_object(&mut self, user_id: UserId) -> i64 {
        let mut user_env = UserEnv {
            global: self.global,
            options: self
                .options
                .as_mut()
                .expect("attach-menu requests run with the initialized option manager"),
            auth_is_bot: self.auth_is_bot,
        };
        self.user_manager.get_user_id_object(
            &mut user_env,
            user_id,
            "get_attachment_menu_bot_object",
        )
    }

    fn on_get_users(&mut self, users: Vec<telegram_api::User>, source: &str) {
        let mut user_env = UserEnv {
            global: self.global,
            options: self
                .options
                .as_mut()
                .expect("attach-menu requests run with the initialized option manager"),
            auth_is_bot: self.auth_is_bot,
        };
        self.user_manager.on_get_users(&mut user_env, users, source)
    }

    fn get_attach_menu_bot_file_source_id(&mut self, user_id: UserId) -> FileSourceId {
        // `FileReferenceManager::create_attach_menu_bot_file_source`
        // (FileReferenceManager.cpp:282-286)
        self.file_reference_manager
            .intern(crate::files::FileSource::AttachMenuBot(user_id))
    }

    fn on_get_icon_document(
        &mut self,
        document: &telegram_api::document,
        expected_sticker: bool,
    ) -> FileId {
        // the narrow `DocumentsManager::on_get_document` collapse: the
        // General-vs-Sticker type derivation reads the document
        // attributes; the remote location registers into the M.12 file
        // plane with the C++ FromServer source
        let has_sticker = document.attributes.iter().any(|attribute| {
            matches!(
                attribute,
                telegram_api::DocumentAttribute::documentAttributeSticker(_)
            )
        });
        if has_sticker != expected_sticker {
            return FileId::new(0, 0);
        }
        let file_type = if has_sticker {
            FileType::Sticker
        } else {
            FileType::Document
        };
        let dc_id = if ChatDcId::is_valid_raw(document.dc_id) {
            ChatDcId::internal(document.dc_id)
        } else {
            ChatDcId::invalid()
        };
        let location = crate::files::FullRemoteFileLocation::from_document(
            file_type,
            document.id,
            document.access_hash,
            dc_id,
            String::from_utf8_lossy(&document.file_reference).into_owned(),
        );
        let remote_name = document
            .attributes
            .iter()
            .find_map(|attribute| match attribute {
                telegram_api::DocumentAttribute::documentAttributeFilename(name) => {
                    Some(name.file_name.clone())
                }
                _ => None,
            })
            .unwrap_or_else(|| document.mime_type.clone());
        let mut file_manager = self.file_manager.lock();
        file_manager.register_remote(
            location,
            crate::files::FileLocationSource::FromServer,
            crate::message_id::DialogId::new(0),
            document.size,
            document.size,
            remote_name,
        )
    }

    fn add_file_source(&mut self, file_id: FileId, source_id: FileSourceId) {
        // the C++ `FileManager::add_file_source` hop routes into the
        // FileReferenceManager, which owns the source registry
        self.file_reference_manager
            .add_file_source(file_id, source_id);
    }

    fn get_file_object(&mut self, file_id: FileId) -> td_api::File {
        self.file_manager.lock().get_file_object(file_id)
    }

    fn store_file_id(&mut self, file_id: FileId, out: &mut Vec<u8>) {
        self.file_manager.lock().store_file(file_id, out);
    }

    fn parse_file_id(
        &mut self,
        parser: &mut crate::store_parse::Parser,
    ) -> Result<FileId, &'static str> {
        self.file_manager.lock().parse_file(parser)
    }
}

/// The [`crate::connection_creator::ConnectionCreatorEnv`] over the whole
/// `Td` — the request arms take the manager out of `Td` and hand the
/// remainder to the env (the [`BackgroundEnv`] convention).
pub(crate) struct ConnectionEnv<'a> {
    pub(crate) td: &'a mut Td,
}

impl crate::connection_creator::ConnectionCreatorEnv for ConnectionEnv<'_> {
    fn binlog_pmc_get(&mut self, key: &[u8]) -> String {
        String::from_utf8_lossy(&self.td.global.binlog_pmc().get_raw(key)).into_owned()
    }

    fn binlog_pmc_set_raw(&mut self, key: &[u8], value: &[u8]) {
        self.td.global.binlog_pmc().set_raw(key, value);
    }

    fn binlog_pmc_erase(&mut self, key: &str) {
        self.td.global.binlog_pmc().erase(key);
    }

    fn binlog_pmc_prefix_get(&mut self, prefix: &str) -> Vec<(String, Vec<u8>)> {
        self.td.global.binlog_pmc().prefix_get(prefix)
    }

    fn get_option_boolean(&self, name: &str, default_value: bool) -> bool {
        self.td
            .option_manager
            .as_ref()
            .map_or(default_value, |options| {
                options.get_option_boolean(name, default_value)
            })
    }

    fn set_option_integer(&mut self, name: &str, value: i64) {
        if let Some(options) = self.td.option_manager.as_mut() {
            options.set_option_integer(name, value);
        }
    }

    fn set_option_empty(&mut self, name: &str) {
        if let Some(options) = self.td.option_manager.as_mut() {
            options.set_option_empty(name);
        }
    }

    fn request_config(&mut self, _reopen_sessions: bool) {
        // `send_closure(G()->config_manager(), &ConfigManager::request_config,
        // false)` — the config refetch cycle after the proxy went away. The
        // collapsed config machinery fetches through its own paths; the
        // proxy-aware refetch closes with the net step.
    }

    fn remove_sponsored_dialog(&mut self) {
        let (mut promo_data_manager, mut promo_env) = promo_env_split(self.td);
        promo_data_manager.remove_sponsored_dialog(&mut promo_env);
        self.td.promo_data_manager = promo_data_manager;
    }

    fn reload_promo_data(&mut self) {
        let (mut promo_data_manager, mut promo_env) = promo_env_split(self.td);
        promo_data_manager.reload_promo_data(&mut promo_env);
        self.td.promo_data_manager = promo_data_manager;
    }

    fn update_mtproto_header(&mut self, _proxy: Option<&crate::connection_creator::Proxy>) {
        // `ConnectionCreator::update_mtproto_header` — the net step's
        // session/mtproto-header rebuild (`[blocked: net]`).
    }

    fn on_proxy_state(&mut self, _use_proxy: bool) {
        // `StateManager::on_proxy` — the state flag's consumers (the
        // recoverer's reconnect cycle) are the net-step seams; the flag
        // itself rides the collapsed state world.
    }

    fn ping_via_net(&mut self, _proxy: &crate::connection_creator::Proxy, promise: Promise<f64>) {
        // `GetHostByNameActor::run` + `ping_proxy_resolved` — the
        // `[blocked: net]` resolve/connect seam. Dropping the promise
        // answers with the C++ LambdaPromise drop ("Lost promise") until
        // the net step's ping machinery completes it.
        drop(promise);
    }

    fn test_proxy_via_net(
        &mut self,
        _proxy: &crate::connection_creator::Proxy,
        _dc_id: i32,
        _timeout: f64,
        promise: Promise<()>,
    ) {
        // `ProxyChecker::test_proxy` — the `[blocked: net]` handshake
        // seam; the promise resolves with the C++ LambdaPromise drop.
        drop(promise);
    }
}

/// The [`crate::country_info_manager::CountryInfoManagerEnv`] over the
/// whole `Td` — the request arms split the manager out of `Td` and hand
/// the remainder to the env (the [`ConnectionEnv`] convention).
pub(crate) struct CountryEnv<'a> {
    pub(crate) td: &'a mut Td,
}

impl crate::country_info_manager::CountryInfoManagerEnv for CountryEnv<'_> {
    fn close_flag(&self) -> bool {
        self.td.close_flag != 0
    }

    fn is_bot(&self) -> bool {
        self.td.auth_manager.is_bot()
    }

    fn have_option(&self, name: &str) -> bool {
        self.td
            .option_manager
            .as_ref()
            .is_some_and(|options| options.have_option(name))
    }

    fn get_option_string(&self, name: &str, default_value: &str) -> String {
        self.td.option_manager.as_ref().map_or_else(
            || default_value.to_owned(),
            |options| options.get_option_string(name, default_value),
        )
    }

    /// `to_lower(td_->language_pack_manager_->get_main_language_code())`
    /// (CountryInfoManager.cpp:188-190) — the collapsed manager runs
    /// through its own env, like [`Td::init_language_pack_manager`].
    fn get_main_language_code(&mut self) -> String {
        let mut env = LanguagePackEnv {
            options: self.td.option_manager.as_mut(),
            updates: &mut self.td.language_pack_updates,
        };
        self.td
            .language_pack_manager
            .get_main_language_code(&mut env)
            .to_ascii_lowercase()
    }

    /// `GetNearestDcQuery::send` (CountryInfoManager.cpp:37-39) — the
    /// unauth dispatch; the promise parks at the Td-side lot until the
    /// answer.
    fn get_nearest_dc_via_net(&mut self, promise: Promise<String>) {
        self.td.nearest_dc_promises.push(promise);
        match self.td.country_net() {
            Some(net) => net.dispatch_unauth(
                CountryNetKind::NearestDc,
                telegram_api::Function::help_getNearestDc(telegram_api::help_getNearestDc),
            ),
            None => tdutils::log_info!("Send help.getNearestDc — [net-inert]"),
        }
    }

    /// `GetCountriesListQuery::send` (CountryInfoManager.cpp:67-69) —
    /// the unauth dispatch with the interned language-code index.
    fn get_countries_list_via_net(&mut self, language_code: &str, hash: i32) {
        match self.td.country_net() {
            Some(net) => {
                let language_code_index = self.td.country_language_codes.len() as u32;
                self.td
                    .country_language_codes
                    .push(std::sync::Arc::from(language_code));
                net.dispatch_unauth(
                    CountryNetKind::CountriesList {
                        language_code_index,
                    },
                    telegram_api::Function::help_getCountriesList(
                        telegram_api::help_getCountriesList {
                            lang_code: language_code.to_owned(),
                            hash,
                        },
                    ),
                )
            }
            None => {
                tdutils::log_info!(
                    "Send help.getCountriesList({language_code}, {hash}) — [net-inert]"
                )
            }
        }
    }
}

/// The `G()`/manager split of the collapsed CountryInfoManager — the
/// request arms and the init site take the manager out of `Td` (the
/// `promo_env_split` convention) so the env can hold the remainder.
pub(crate) fn country_env_split(
    td: &mut Td,
) -> (
    CountryEnv<'_>,
    crate::country_info_manager::CountryInfoManager,
) {
    let manager = std::mem::take(&mut td.country_info_manager);
    let env = CountryEnv { td };
    (env, manager)
}

/// The [`crate::privacy_manager::PrivacyManagerEnv`] +
/// [`crate::auto_download_settings::AutoDownloadSettingsEnv`] over the
/// whole `Td` — the request arms take the manager out of `Td` and hand
/// the remainder to the env (the [`ConnectionEnv`] convention).
pub(crate) struct PrivacyEnv<'a> {
    pub(crate) td: &'a mut Td,
}

/// The disjoint manager/env take-out (the `translation_env_split`
/// convention) for the privacy manager.
pub(crate) fn privacy_env_split(
    td: &mut Td,
) -> (crate::privacy_manager::PrivacyManager, PrivacyEnv<'_>) {
    let manager = std::mem::take(&mut td.privacy_manager);
    (manager, PrivacyEnv { td })
}

impl crate::privacy_manager::PrivacyManagerEnv for PrivacyEnv<'_> {
    fn close_flag(&self) -> bool {
        self.td.global.close_flag()
    }

    fn have_dialog_force(&mut self, dialog_id: crate::dialog_id::DialogId, source: &str) -> bool {
        crate::dialog_manager::have_dialog_force(self.td, dialog_id, source)
    }

    fn is_megagroup_channel(&mut self, channel_id: crate::chat_manager::ChannelId) -> bool {
        // `ChatManager::is_megagroup_channel` — the unloaded-channel read
        // is the M.6 stub (the stub inventory).
        crate::dialog_manager::is_megagroup_channel(channel_id)
    }

    fn get_user_ids_object(
        &mut self,
        user_ids: &[crate::user_manager::UserId],
        _source: &str,
    ) -> Vec<i64> {
        user_ids.iter().map(|&user_id| user_id.get()).collect()
    }

    fn get_chat_ids_object(
        &mut self,
        dialog_ids: &[crate::dialog_id::DialogId],
        source: &str,
    ) -> Vec<i64> {
        crate::dialog_manager::get_chat_ids_object(dialog_ids, source)
    }

    fn send_update_privacy_rules(&mut self, update: td_api::updateUserPrivacySettingRules) {
        self.td
            .send_update(td_api::Object::updateUserPrivacySettingRules(update));
    }

    fn on_update_online_status_privacy(&mut self) {
        let this = &mut *self.td;
        let mut user_env = UserEnv {
            global: &mut this.global,
            options: this
                .option_manager
                .as_mut()
                .expect("user requests run with the initialized option manager"),
            auth_is_bot: this.auth_manager.is_bot(),
        };
        this.user_manager
            .on_update_online_status_privacy(&mut user_env);
    }

    fn on_update_phone_number_privacy(&mut self) {
        let this = &mut *self.td;
        let user_env = UserEnv {
            global: &mut this.global,
            options: this
                .option_manager
                .as_mut()
                .expect("user requests run with the initialized option manager"),
            auth_is_bot: this.auth_manager.is_bot(),
        };
        this.user_manager.on_update_phone_number_privacy(&user_env);
    }

    fn reload_user(&mut self, user_id: crate::user_manager::UserId, source: &str) {
        // `UserManager::reload_user(user_id, Promise<Unit>(), source)`
        // (GlobalPrivacySettings.cpp:253) — the empty-promise refetch
        // over the GetUserMerger
        let this = &mut *self.td;
        let mut user_env = UserEnv {
            global: &mut this.global,
            options: this
                .option_manager
                .as_mut()
                .expect("user requests run with the initialized option manager"),
            auth_is_bot: this.auth_manager.is_bot(),
        };
        this.user_manager.reload_user(
            &mut user_env,
            user_id,
            tdutils::promise::Promise::default(),
            source,
        );
    }

    fn hide_archive_and_mute_suggested_action(&mut self) {
        let this = &mut *self.td;
        let crate::td::Td {
            global,
            option_manager,
            user_manager,
            device_token_manager,
            auth_manager,
            suggested_action_manager,
            account_updates,
            ..
        } = this;
        let mut action = crate::suggested_action::SuggestedAction::default();
        action.init(crate::suggested_action::SuggestedActionType::EnableArchiveAndMuteNewChats);
        let mut account_env = AccountEnv {
            global,
            options: option_manager.as_mut(),
            user_manager,
            device_token_manager,
            auth_is_bot: auth_manager.is_bot(),
            updates: account_updates,
            net: None,
        };
        suggested_action_manager.hide_suggested_action(&mut account_env, action);
    }

    fn get_privacy_via_net(&mut self, key: crate::privacy_manager::UserPrivacySettingType) {
        // `GetPrivacyQuery::send` (PrivacyManager.cpp:33-35) — the queued
        // caller promises ride the `PrivacyManager` state until
        // `on_get_user_privacy_settings` drains them.
        match self.td.privacy_net() {
            Some(net) => net.dispatch(
                PrivacyNetKind::GetPrivacy { setting: key },
                telegram_api::Function::account_getPrivacy(telegram_api::account_getPrivacy {
                    key: Some(key.get_input_privacy_key()),
                }),
            ),
            None => tdutils::log_info!("Get privacy — [net-inert]"),
        }
    }

    fn set_privacy_via_net(
        &mut self,
        key: crate::privacy_manager::UserPrivacySettingType,
        rules: crate::privacy_manager::UserPrivacySettingRules,
        promise: Promise<()>,
    ) {
        // `SetPrivacyQuery::send` (PrivacyManager.cpp:61-64) — the input
        // rules resolve at the send leg.
        self.td
            .privacy_promises
            .push(PendingPrivacyQuery::SetPrivacy { promise });
        match self.td.privacy_net() {
            Some(net) => net.dispatch(
                PrivacyNetKind::SetPrivacy { setting: key },
                telegram_api::Function::account_setPrivacy(telegram_api::account_setPrivacy {
                    key: Some(key.get_input_privacy_key()),
                    rules: rules.get_input_privacy_rules(self),
                }),
            ),
            None => tdutils::log_info!("Set privacy — [net-inert]"),
        }
    }

    fn get_global_privacy_via_net(
        &mut self,
        promise: Promise<crate::privacy_manager::GlobalPrivacySettings>,
    ) {
        // `GetGlobalPrivacySettingsQuery::send`
        // (GlobalPrivacySettings.cpp:33-35) — the `{{"me"}}` dispatch
        // band keys on the own user.
        self.td
            .privacy_promises
            .push(PendingPrivacyQuery::GetGlobal { promise });
        match self.td.privacy_net() {
            Some(net) => net.dispatch(
                PrivacyNetKind::GetGlobalPrivacySettings,
                telegram_api::Function::account_getGlobalPrivacySettings(
                    telegram_api::account_getGlobalPrivacySettings,
                ),
            ),
            None => tdutils::log_info!("Get global privacy settings — [net-inert]"),
        }
    }

    fn set_global_privacy_via_net(
        &mut self,
        settings: crate::privacy_manager::GlobalPrivacySettings,
        promise: Promise<()>,
    ) {
        // `SetGlobalPrivacySettingsQuery::send`
        // (GlobalPrivacySettings.cpp:59-62).
        self.td
            .privacy_promises
            .push(PendingPrivacyQuery::SetGlobal { promise });
        match self.td.privacy_net() {
            Some(net) => net.dispatch(
                PrivacyNetKind::SetGlobalPrivacySettings,
                telegram_api::Function::account_setGlobalPrivacySettings(
                    telegram_api::account_setGlobalPrivacySettings {
                        settings: Some(settings.get_input_global_privacy_settings()),
                    },
                ),
            ),
            None => tdutils::log_info!("Set global privacy settings — [net-inert]"),
        }
    }

    fn on_get_users(&mut self, users: Vec<telegram_api::User>, source: &str) {
        let mut env = UserEnv {
            global: &mut self.td.global,
            options: self
                .td
                .option_manager
                .as_mut()
                .expect("privacy calls run with the initialized option manager"),
            auth_is_bot: self.td.auth_manager.is_bot(),
        };
        self.td.user_manager.on_get_users(&mut env, users, source);
    }

    fn on_get_chats(&mut self, chats: Vec<telegram_api::Chat>, source: &str) {
        let td = &mut *self.td;
        let mut env = UserEnv {
            global: &mut td.global,
            options: td
                .option_manager
                .as_mut()
                .expect("privacy calls run with the initialized option manager"),
            auth_is_bot: td.auth_manager.is_bot(),
        };
        td.chat_manager
            .on_get_chats(&mut td.user_manager, &mut env, chats, source);
    }

    fn have_accessible_user(&self, user_id: crate::user_manager::UserId) -> bool {
        self.td.user_manager.have_accessible_user(user_id)
    }

    fn get_input_users_force(
        &mut self,
        user_ids: &[crate::user_manager::UserId],
    ) -> Vec<telegram_api::InputUser> {
        let env = UserEnv {
            global: &mut self.td.global,
            options: self
                .td
                .option_manager
                .as_mut()
                .expect("privacy calls run with the initialized option manager"),
            auth_is_bot: self.td.auth_manager.is_bot(),
        };
        self.td.user_manager.get_input_users_force(&env, user_ids)
    }

    fn have_chat(&self, chat_id: crate::chat_manager::ChatId) -> bool {
        self.td.chat_manager.have_chat(chat_id)
    }

    fn have_channel(&self, channel_id: crate::chat_manager::ChannelId) -> bool {
        self.td.chat_manager.have_channel(channel_id)
    }

    fn force_create_dialog(&mut self, dialog_id: crate::dialog_id::DialogId, source: &str) {
        crate::dialog_manager::force_create_dialog(self.td, dialog_id, source);
    }
}

impl crate::auto_download_settings::AutoDownloadSettingsEnv for PrivacyEnv<'_> {
    fn get_auto_download_settings_via_net(
        &mut self,
        promise: Promise<td_api::AutoDownloadSettingsPresets>,
    ) {
        // `GetAutoDownloadSettingsQuery::send` (cpp:44-45).
        self.td
            .auto_download_promises
            .push(PendingAutoDownloadQuery::GetPresets { promise });
        match self.td.auto_download_net() {
            Some(net) => net.dispatch(
                AutoDownloadNetKind::GetAutoDownloadSettings,
                telegram_api::Function::account_getAutoDownloadSettings(
                    telegram_api::account_getAutoDownloadSettings,
                ),
            ),
            None => tdutils::log_info!("Get auto-download settings — [net-inert]"),
        }
    }

    fn set_auto_download_settings_via_net(
        &mut self,
        is_roaming: bool,
        is_wifi: bool,
        settings: crate::auto_download_settings::AutoDownloadSettings,
        promise: Promise<()>,
    ) {
        // `SaveAutoDownloadSettingsQuery::send` (cpp:76-80) — the
        // roaming/wifi flag pair (the C++ passes flags = 0 and lets the
        // generated store OR the bits).
        self.td
            .auto_download_promises
            .push(PendingAutoDownloadQuery::Save { promise });
        match self.td.auto_download_net() {
            Some(net) => net.dispatch(
                AutoDownloadNetKind::SaveAutoDownloadSettings,
                telegram_api::Function::account_saveAutoDownloadSettings(
                    telegram_api::account_saveAutoDownloadSettings {
                        flags: 0,
                        low: is_roaming,
                        high: is_wifi,
                        settings: Some(
                            crate::auto_download_settings::get_input_auto_download_settings(
                                &settings,
                            ),
                        ),
                    },
                ),
            ),
            None => tdutils::log_info!("Save auto-download settings — [net-inert]"),
        }
    }
}

