/// The `G()`/manager slice of the collapsed SponsoredMessageManager +
/// PromoDataManager + MessageImportManager trio (M.26) — the whole-Td
/// shape (the `star_env_split` convention): the manager is always
/// `std::mem::take`n out for the call, so the env may hold the full
/// `&mut Td` (the net senders reach the dispatcher and the dialog peer
/// resolver).
pub(crate) struct TdSponsoredEnv<'a> {
    pub(crate) td: &'a mut Td,
}

impl crate::sponsored_message_manager::SponsoredMessageManagerEnv for TdSponsoredEnv<'_> {
    fn close_flag(&self) -> bool {
        self.td.global.close_flag()
    }

    fn now(&self) -> f64 {
        tdutils::time::now()
    }

    fn get_option_boolean(&self, name: &str, default_value: bool) -> bool {
        self.td
            .option_manager
            .as_ref()
            .map_or(default_value, |options| {
                options.get_option_boolean(name, default_value)
            })
    }

    fn get_my_sponsored_enabled(&self) -> bool {
        self.td.user_manager.get_my_sponsored_enabled()
    }

    fn on_get_users(&mut self, users: Vec<telegram_api::User>, source: &'static str) {
        let options = self.td.option_manager.as_mut();
        if let Some(options) = options {
            let mut env = UserEnv {
                global: &mut self.td.global,
                options,
                auth_is_bot: self.td.auth_manager.is_bot(),
            };
            self.td.user_manager.on_get_users(&mut env, users, source);
        }
    }

    fn on_get_chats(&mut self, chats: Vec<telegram_api::Chat>, source: &'static str) {
        let options = self.td.option_manager.as_mut();
        if let Some(options) = options {
            let mut env = UserEnv {
                global: &mut self.td.global,
                options,
                auth_is_bot: self.td.auth_manager.is_bot(),
            };
            self.td
                .chat_manager
                .on_get_chats(&mut self.td.user_manager, &mut env, chats, source);
        }
    }

    fn check_dialog_access(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
        _source: &'static str,
    ) -> tdutils::status::Result<()> {
        if !have_dialog_info_of(&self.td.user_manager, dialog_id) {
            if !dialog_id.is_valid() {
                return tdutils::status::Result::from_status(tdutils::status::Status::error(
                    400,
                    "Invalid chat identifier specified",
                ));
            }
            return tdutils::status::Result::from_status(tdutils::status::Status::error(
                400,
                "Chat not found",
            ));
        }
        tdutils::status::Result::Ok(())
    }

    fn have_dialog_info(&self, dialog_id: crate::dialog_id::DialogId) -> bool {
        have_dialog_info_of(&self.td.user_manager, dialog_id)
    }

    fn force_create_dialog(
        &mut self,
        _dialog_id: crate::dialog_id::DialogId,
        _source: &'static str,
    ) {
        // M.6 stub: messages_manager_->force_create_dialog
    }

    fn get_chat_id_object(
        &self,
        dialog_id: crate::dialog_id::DialogId,
        _source: &'static str,
    ) -> i64 {
        dialog_id.get_chat_id().get()
    }

    fn can_get_message_video_advertisements(&self, _message_full_id: MessageFullId) -> bool {
        false // the M.10 message-plane probe answers the not-found band
    }

    fn get_accent_color_id_object(
        &self,
        accent_color_id: crate::peer_color::AccentColorId,
        fallback_accent_color_id: crate::peer_color::AccentColorId,
    ) -> i32 {
        if accent_color_id.is_valid() {
            accent_color_id.get()
        } else {
            fallback_accent_color_id.get()
        }
    }

    fn get_sponsored_message_text(
        &mut self,
        sponsored_message: &telegram_api::SponsoredMessage,
    ) -> String {
        sponsored_message.message.clone()
    }

    fn get_sponsored_message_content(
        &mut self,
        text: String,
        media: Option<Box<telegram_api::MessageMedia>>,
    ) -> crate::sponsored_message_manager::SponsoredContent {
        let content_type = match media {
            Some(media) => match *media {
                telegram_api::MessageMedia::messageMediaPhoto(_) => {
                    crate::sponsored_message_manager::SponsoredContentType::Photo
                }
                telegram_api::MessageMedia::messageMediaDocument(_) => {
                    crate::sponsored_message_manager::SponsoredContentType::Animation
                }
                _ => crate::sponsored_message_manager::SponsoredContentType::Unsupported,
            },
            None => crate::sponsored_message_manager::SponsoredContentType::Text,
        };
        crate::sponsored_message_manager::SponsoredContent::new(content_type, text, false)
    }

    fn get_message_content_object(
        &self,
        _content: &crate::sponsored_message_manager::SponsoredContent,
    ) -> Option<td_api::MessageContent> {
        None // the degraded builder (null content)
    }

    fn get_sponsored_photo(&mut self, photo: Option<telegram_api::Photo>) -> crate::photo::Photo {
        match photo {
            Some(_photo) => crate::photo::Photo::default(),
            None => crate::photo::Photo::default(),
        }
    }

    fn get_photo_object(&self, _photo: &crate::photo::Photo) -> Option<td_api::Photo> {
        None
    }

    fn send_get_sponsored_messages_query(
        &mut self,
        dialog_id: crate::dialog_id::DialogId,
        message_id: crate::messages_manager::MessageId,
    ) {
        // `GetSponsoredMessagesQuery::send` (cpp:59-70) — the
        // read-access input peer; the C++ CHECK band logs when the peer
        // is missing (the None arm skips the send like the C++ actor
        // would abort the handler).
        let Some(net) = self.td.sponsored_net() else {
            return tdutils::log_info!("Send messages.getSponsoredMessages — [net-inert]");
        };
        let Some(peer) = crate::dialog_manager::get_input_peer(
            self.td,
            dialog_id,
            crate::user_manager::AccessRights::Read,
        ) else {
            tdutils::log_info!("GetSponsoredMessagesQuery — no input peer for {dialog_id:?}");
            return;
        };
        let flags = usize::from(message_id.get() != 0) as i32;
        net.dispatch(
            SponsoredNetKind::GetSponsoredMessages { dialog_id },
            telegram_api::Function::messages_getSponsoredMessages(
                telegram_api::messages_getSponsoredMessages {
                    flags,
                    peer: Some(Box::new(peer)),
                    msg_id: message_id.get_server_message_id().get(),
                },
            ),
        );
    }

    fn send_get_sponsored_peers_query(&mut self, query: &str) {
        // `GetSponsoredPeersQuery::send` (cpp:191-193).
        match self.td.sponsored_net() {
            Some(net) => {
                let query_index = self.td.sponsored_peer_queries.len() as u32;
                self.td
                    .sponsored_peer_queries
                    .push(std::sync::Arc::from(query));
                net.dispatch(
                    SponsoredNetKind::GetSponsoredPeers { query_index },
                    telegram_api::Function::contacts_getSponsoredPeers(
                        telegram_api::contacts_getSponsoredPeers {
                            q: query.to_owned(),
                        },
                    ),
                )
            }
            None => {
                tdutils::log_info!("Send contacts.getSponsoredPeers({query}) — [net-inert]")
            }
        }
    }

    fn send_view_sponsored_message_query(&mut self, random_id: &[u8]) {
        // `ViewSponsoredMessageQuery::send` (cpp:83-85) — the
        // fire-and-forget form.
        match self.td.sponsored_net() {
            Some(net) => net.dispatch(
                SponsoredNetKind::ViewSponsoredMessage,
                telegram_api::Function::messages_viewSponsoredMessage(
                    telegram_api::messages_viewSponsoredMessage {
                        random_id: random_id.to_vec(),
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send messages.viewSponsoredMessage — [net-inert]")
            }
        }
    }

    fn send_click_sponsored_message_query(
        &mut self,
        query: crate::sponsored_message_manager::PendingClickQuery,
    ) {
        // `ClickSponsoredMessageQuery::send` (cpp:103-105) — the flag
        // pair; the promise parks in the manager's click lot.
        let crate::sponsored_message_manager::PendingClickQuery {
            random_id,
            is_media_click,
            from_fullscreen,
            promise,
        } = query;
        self.td
            .sponsored_message_manager
            .park_click_promise(promise);
        match self.td.sponsored_net() {
            Some(net) => net.dispatch(
                SponsoredNetKind::ClickSponsoredMessage,
                telegram_api::Function::messages_clickSponsoredMessage(
                    telegram_api::messages_clickSponsoredMessage {
                        flags: (is_media_click as i32) | ((from_fullscreen as i32) << 1),
                        media: is_media_click,
                        fullscreen: from_fullscreen,
                        random_id,
                    },
                ),
            ),
            None => tdutils::log_info!("Send messages.clickSponsoredMessage — [net-inert]"),
        }
    }

    fn send_report_sponsored_message_query(
        &mut self,
        query: crate::sponsored_message_manager::PendingReportQuery,
    ) {
        // `ReportSponsoredMessageQuery::send` (cpp:125-127).
        let crate::sponsored_message_manager::PendingReportQuery {
            random_id,
            option_id,
            promise,
        } = query;
        self.td
            .sponsored_message_manager
            .park_report_promise(promise);
        match self.td.sponsored_net() {
            Some(net) => net.dispatch(
                SponsoredNetKind::ReportSponsoredMessage,
                telegram_api::Function::messages_reportSponsoredMessage(
                    telegram_api::messages_reportSponsoredMessage {
                        random_id,
                        option: option_id,
                    },
                ),
            ),
            None => {
                tdutils::log_info!("Send messages.reportSponsoredMessage — [net-inert]")
            }
        }
    }
}

/// The field-level `dialog_manager_->have_dialog_info` (the user half is
/// real; the chat/channel halves are the M.6 stub inventory).
fn have_dialog_info_of(user_manager: &UserManager, dialog_id: crate::dialog_id::DialogId) -> bool {
    match dialog_id.get_type() {
        crate::dialog_id::DialogType::User => {
            user_manager.have_accessible_user(dialog_id.get_user_id())
        }
        crate::dialog_id::DialogType::Chat | crate::dialog_id::DialogType::Channel => false,
        crate::dialog_id::DialogType::SecretChat => {
            user_manager.have_secret_chat(dialog_id.get_secret_chat_id())
        }
        crate::dialog_id::DialogType::None => false,
    }
}

